window.LAWDATA=window.LAWDATA||{};window.LAWDATA["shoho"]={"key":"shoho","id":"132AC0000000048","title":"商法","num":"明治三十二年法律第四十八号","fetched":"2026-11-09","articles":[{"num":"1","title":"第一条","caption":"（趣旨等）","path":["第一編　総則","第一章　通則"],"paras":[{"n":"1","s":[{"t":"商人の営業、商行為その他商事については、他の法律に特別の定めがあるものを除くほか、この法律の定めるところによる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"商事に関し、この法律に定めがない事項については商慣習に従い、商慣習がないときは、民法（明治二十九年法律第八十九号）の定めるところによる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"0afc4ded3922"},{"num":"2","title":"第二条","caption":"（公法人の商行為）","path":["第一編　総則","第一章　通則"],"paras":[{"n":"1","s":[{"t":"公法人が行う商行為については、法令に別段の定めがある場合を除き、この法律の定めるところによる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ac2acb416e78"},{"num":"3","title":"第三条","caption":"（一方的商行為）","path":["第一編　総則","第一章　通則"],"paras":[{"n":"1","s":[{"t":"当事者の一方のために商行為となる行為については、この法律をその双方に適用する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"当事者の一方が二人以上ある場合において、その一人のために商行為となる行為については、この法律をその全員に適用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2080ffd4ddf5"},{"num":"4","title":"第四条","caption":"（定義）","path":["第一編　総則","第二章　商人"],"paras":[{"n":"1","s":[{"t":"この法律において「商人」とは、自己の名をもって商行為をすることを業とする者をいう。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"店舗その他これに類似する設備によって物品を販売することを業とする者又は鉱業を営む者は、商行為を行うことを業としない者であっても、これを商人とみなす。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c1e40864a5ae"},{"num":"5","title":"第五条","caption":"（未成年者登記）","path":["第一編　総則","第二章　商人"],"paras":[{"n":"1","s":[{"t":"未成年者が前条の営業を行うときは、その登記をしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"bad78450990e"},{"num":"6","title":"第六条","caption":"（後見人登記）","path":["第一編　総則","第二章　商人"],"paras":[{"n":"1","s":[{"t":"後見人が被後見人のために第四条の営業を行うときは、その登記をしなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"後見人の代理権に加えた制限は、善意の第三者に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"eb7342c76bd4"},{"num":"7","title":"第七条","caption":"（小商人）","path":["第一編　総則","第二章　商人"],"paras":[{"n":"1","s":[{"t":"第五条、前条、次章、第十一条第二項、第十五条第二項、第十七条第二項前段、第五章及び第二十二条の規定は、小商人（商人のうち、法務省令で定めるその営業のために使用する財産の価額が法務省令で定める金額を超えないものをいう。）については、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"78372f8277dc"},{"num":"8","title":"第八条","caption":"（通則）","path":["第一編　総則","第三章　商業登記"],"paras":[{"n":"1","s":[{"t":"この編の規定により登記すべき事項は、当事者の申請により、商業登記法（昭和三十八年法律第百二十五号）の定めるところに従い、商業登記簿にこれを登記する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"649b239c1707"},{"num":"9","title":"第九条","caption":"（登記の効力）","path":["第一編　総則","第三章　商業登記"],"paras":[{"n":"1","s":[{"t":"この編の規定により登記すべき事項は、登記の後でなければ、これをもって善意の第三者に対抗することができない。","kind":"plain"},{"t":"登記の後であっても、第三者が正当な事由によってその登記があることを知らなかったときは、同様とする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"故意又は過失によって不実の事項を登記した者は、その事項が不実であることをもって善意の第三者に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ce3fa8145d7a"},{"num":"10","title":"第十条","caption":"（変更の登記及び消滅の登記）","path":["第一編　総則","第三章　商業登記"],"paras":[{"n":"1","s":[{"t":"この編の規定により登記した事項に変更が生じ、又はその事項が消滅したときは、当事者は、遅滞なく、変更の登記又は消滅の登記をしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6da85723e968"},{"num":"11","title":"第十一条","caption":"（商号の選定）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"商人（会社及び外国会社を除く。以下この編において同じ。）は、その氏、氏名その他の名称をもってその商号とすることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"商人は、その商号の登記をすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c6868d9a4d1d"},{"num":"12","title":"第十二条","caption":"（他の商人と誤認させる名称等の使用の禁止）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"何人も、不正の目的をもって、他の商人であると誤認されるおそれのある名称又は商号を使用してはならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定に違反する名称又は商号の使用によって営業上の利益を侵害され、又は侵害されるおそれがある商人は、その営業上の利益を侵害する者又は侵害するおそれがある者に対し、その侵害の停止又は予防を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"433635998054"},{"num":"13","title":"第十三条","caption":"（過料）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"前条第一項の規定に違反した者は、百万円以下の過料に処する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a997295f3bad"},{"num":"14","title":"第十四条","caption":"（自己の商号の使用を他人に許諾した商人の責任）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"自己の商号を使用して営業又は事業を行うことを他人に許諾した商人は、当該商人が当該営業を行うものと誤認して当該他人と取引をした者に対し、当該他人と連帯して、当該取引によって生じた債務を弁済する責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"66b4c184af7d"},{"num":"15","title":"第十五条","caption":"（商号の譲渡）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"商人の商号は、営業とともにする場合又は営業を廃止する場合に限り、譲渡することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による商号の譲渡は、登記をしなければ、第三者に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6aa3a6d5c9ee"},{"num":"16","title":"第十六条","caption":"（営業譲渡人の競業の禁止）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"営業を譲渡した商人（以下この章において「譲渡人」という。）は、当事者の別段の意思表示がない限り、同一の市町村（特別区を含むものとし、地方自治法（昭和二十二年法律第六十七号）第二百五十二条の十九第一項の指定都市にあっては、区又は総合区。以下同じ。）の区域内及びこれに隣接する市町村の区域内においては、その営業を譲渡した日から二十年間は、同一の営業を行ってはならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"譲渡人が同一の営業を行わない旨の特約をした場合には、その特約は、その営業を譲渡した日から三十年の期間内に限り、その効力を有する。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定にかかわらず、譲渡人は、不正の競争の目的をもって同一の営業を行ってはならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2c52d0afc081"},{"num":"17","title":"第十七条","caption":"（譲渡人の商号を使用した譲受人の責任等）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"営業を譲り受けた商人（以下この章において「譲受人」という。）が譲渡人の商号を引き続き使用する場合には、その譲受人も、譲渡人の営業によって生じた債務を弁済する責任を負う。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、営業を譲渡した後、遅滞なく、譲受人が譲渡人の債務を弁済する責任を負わない旨を登記した場合には、適用しない。","kind":"plain"},{"t":"営業を譲渡した後、遅滞なく、譲受人及び譲渡人から第三者に対しその旨の通知をした場合において、その通知を受けた第三者についても、同様とする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"譲受人が第一項の規定により譲渡人の債務を弁済する責任を負う場合には、譲渡人の責任は、営業を譲渡した日後二年以内に請求又は請求の予告をしない債権者に対しては、その期間を経過した時に消滅する。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"第一項に規定する場合において、譲渡人の営業によって生じた債権について、その譲受人にした弁済は、弁済者が善意でかつ重大な過失がないときは、その効力を有する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"90848b40bdee"},{"num":"18","title":"第十八条","caption":"（譲受人による債務の引受け）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"譲受人が譲渡人の商号を引き続き使用しない場合においても、譲渡人の営業によって生じた債務を引き受ける旨の広告をしたときは、譲渡人の債権者は、その譲受人に対して弁済の請求をすることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"譲受人が前項の規定により譲渡人の債務を弁済する責任を負う場合には、譲渡人の責任は、同項の広告があった日後二年以内に請求又は請求の予告をしない債権者に対しては、その期間を経過した時に消滅する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"bc083e9e3ce2"},{"num":"18_2","title":"第十八条の二","caption":"（詐害営業譲渡に係る譲受人に対する債務の履行の請求）","path":["第一編　総則","第四章　商号"],"paras":[{"n":"1","s":[{"t":"譲渡人が譲受人に承継されない債務の債権者（以下この条において「残存債権者」という。）を害することを知って営業を譲渡した場合には、残存債権者は、その譲受人に対して、承継した財産の価額を限度として、当該債務の履行を請求することができる。","kind":"main"},{"t":"ただし、その譲受人が営業の譲渡の効力が生じた時において残存債権者を害することを知らなかったときは、この限りでない。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"譲受人が前項の規定により同項の債務を履行する責任を負う場合には、当該責任は、譲渡人が残存債権者を害することを知って営業を譲渡したことを知った時から二年以内に請求又は請求の予告をしない残存債権者に対しては、その期間を経過した時に消滅する。","kind":"plain"},{"t":"営業の譲渡の効力が生じた日から十年を経過したときも、同様とする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"譲渡人について破産手続開始の決定又は再生手続開始の決定があったときは、残存債権者は、譲受人に対して第一項の規定による請求をする権利を行使することができない。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"d050a53b45c7"},{"num":"19","title":"第十九条","caption":"","path":["第一編　総則","第五章　商業帳簿"],"paras":[{"n":"1","s":[{"t":"商人の会計は、一般に公正妥当と認められる会計の慣行に従うものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"商人は、その営業のために使用する財産について、法務省令で定めるところにより、適時に、正確な商業帳簿（会計帳簿及び貸借対照表をいう。以下この条において同じ。）を作成しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"商人は、帳簿閉鎖の時から十年間、その商業帳簿及びその営業に関する重要な資料を保存しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"裁判所は、申立てにより又は職権で、訴訟の当事者に対し、商業帳簿の全部又は一部の提出を命ずることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"13422be11d8b"},{"num":"20","title":"第二十条","caption":"（支配人）","path":["第一編　総則","第六章　商業使用人"],"paras":[{"n":"1","s":[{"t":"商人は、支配人を選任し、その営業所において、その営業を行わせることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"4c9e78640eb3"},{"num":"21","title":"第二十一条","caption":"（支配人の代理権）","path":["第一編　総則","第六章　商業使用人"],"paras":[{"n":"1","s":[{"t":"支配人は、商人に代わってその営業に関する一切の裁判上又は裁判外の行為をする権限を有する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"支配人は、他の使用人を選任し、又は解任することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"支配人の代理権に加えた制限は、善意の第三者に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"8a226620d985"},{"num":"22","title":"第二十二条","caption":"（支配人の登記）","path":["第一編　総則","第六章　商業使用人"],"paras":[{"n":"1","s":[{"t":"商人が支配人を選任したときは、その登記をしなければならない。","kind":"plain"},{"t":"支配人の代理権の消滅についても、同様とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"42df5b1334e1"},{"num":"23","title":"第二十三条","caption":"（支配人の競業の禁止）","path":["第一編　総則","第六章　商業使用人"],"paras":[{"n":"1","s":[{"t":"支配人は、商人の許可を受けなければ、次に掲げる行為をしてはならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"自ら営業を行うこと。","kind":"plain"}]},{"n":"二","s":[{"t":"自己又は第三者のためにその商人の営業の部類に属する取引をすること。","kind":"plain"}]},{"n":"三","s":[{"t":"他の商人又は会社若しくは外国会社の使用人となること。","kind":"plain"}]},{"n":"四","s":[{"t":"会社の取締役、執行役又は業務を執行する社員となること。","kind":"plain"}]}]},{"n":"２","s":[{"t":"支配人が前項の規定に違反して同項第二号に掲げる行為をしたときは、当該行為によって支配人又は第三者が得た利益の額は、商人に生じた損害の額と推定する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"371c6c1b0ade"},{"num":"24","title":"第二十四条","caption":"（表見支配人）","path":["第一編　総則","第六章　商業使用人"],"paras":[{"n":"1","s":[{"t":"商人の営業所の営業の主任者であることを示す名称を付した使用人は、当該営業所の営業に関し、一切の裁判外の行為をする権限を有するものとみなす。","kind":"main"},{"t":"ただし、相手方が悪意であったときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"046e2e9f9fe3"},{"num":"25","title":"第二十五条","caption":"（ある種類又は特定の事項の委任を受けた使用人）","path":["第一編　総則","第六章　商業使用人"],"paras":[{"n":"1","s":[{"t":"商人の営業に関するある種類又は特定の事項の委任を受けた使用人は、当該事項に関する一切の裁判外の行為をする権限を有する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の使用人の代理権に加えた制限は、善意の第三者に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5702f27abb7f"},{"num":"26","title":"第二十六条","caption":"（物品の販売等を目的とする店舗の使用人）","path":["第一編　総則","第六章　商業使用人"],"paras":[{"n":"1","s":[{"t":"物品の販売等（販売、賃貸その他これらに類する行為をいう。以下この条において同じ。）を目的とする店舗の使用人は、その店舗に在る物品の販売等をする権限を有するものとみなす。","kind":"main"},{"t":"ただし、相手方が悪意であったときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"759ee2e1248d"},{"num":"27","title":"第二十七条","caption":"（通知義務）","path":["第一編　総則","第七章　代理商"],"paras":[{"n":"1","s":[{"t":"代理商（商人のためにその平常の営業の部類に属する取引の代理又は媒介をする者で、その商人の使用人でないものをいう。以下この章において同じ。）は、取引の代理又は媒介をしたときは、遅滞なく、商人に対して、その旨の通知を発しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b14e24f6ddcd"},{"num":"28","title":"第二十八条","caption":"（代理商の競業の禁止）","path":["第一編　総則","第七章　代理商"],"paras":[{"n":"1","s":[{"t":"代理商は、商人の許可を受けなければ、次に掲げる行為をしてはならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"自己又は第三者のためにその商人の営業の部類に属する取引をすること。","kind":"plain"}]},{"n":"二","s":[{"t":"その商人の営業と同種の事業を行う会社の取締役、執行役又は業務を執行する社員となること。","kind":"plain"}]}]},{"n":"２","s":[{"t":"代理商が前項の規定に違反して同項第一号に掲げる行為をしたときは、当該行為によって代理商又は第三者が得た利益の額は、商人に生じた損害の額と推定する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2c9555cdad4e"},{"num":"29","title":"第二十九条","caption":"（通知を受ける権限）","path":["第一編　総則","第七章　代理商"],"paras":[{"n":"1","s":[{"t":"物品の販売又はその媒介の委託を受けた代理商は、第五百二十六条第二項の通知その他売買に関する通知を受ける権限を有する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d98ef9ad34fe"},{"num":"30","title":"第三十条","caption":"（契約の解除）","path":["第一編　総則","第七章　代理商"],"paras":[{"n":"1","s":[{"t":"商人及び代理商は、契約の期間を定めなかったときは、二箇月前までに予告し、その契約を解除することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定にかかわらず、やむを得ない事由があるときは、商人及び代理商は、いつでもその契約を解除することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"54a6928afd6c"},{"num":"31","title":"第三十一条","caption":"（代理商の留置権）","path":["第一編　総則","第七章　代理商"],"paras":[{"n":"1","s":[{"t":"代理商は、取引の代理又は媒介をしたことによって生じた債権の弁済期が到来しているときは、その弁済を受けるまでは、商人のために当該代理商が占有する物又は有価証券を留置することができる。","kind":"main"},{"t":"ただし、当事者が別段の意思表示をしたときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"9462a7692a12"},{"num":"32:500","title":"第三十二条から第五百条まで","caption":"","path":["第一編　総則","第七章　代理商"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"501","title":"第五百一条","caption":"（絶対的商行為）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"次に掲げる行為は、商行為とする。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"利益を得て譲渡する意思をもってする動産、不動産若しくは有価証券の有償取得又はその取得したものの譲渡を目的とする行為","kind":"plain"}]},{"n":"二","s":[{"t":"他人から取得する動産又は有価証券の供給契約及びその履行のためにする有償取得を目的とする行為","kind":"plain"}]},{"n":"三","s":[{"t":"取引所においてする取引","kind":"plain"}]},{"n":"四","s":[{"t":"手形その他の商業証券に関する行為","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"3b18f1774340"},{"num":"502","title":"第五百二条","caption":"（営業的商行為）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"次に掲げる行為は、営業としてするときは、商行為とする。","kind":"main"},{"t":"ただし、専ら賃金を得る目的で物を製造し、又は労務に従事する者の行為は、この限りでない。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"賃貸する意思をもってする動産若しくは不動産の有償取得若しくは賃借又はその取得し若しくは賃借したものの賃貸を目的とする行為","kind":"plain"}]},{"n":"二","s":[{"t":"他人のためにする製造又は加工に関する行為","kind":"plain"}]},{"n":"三","s":[{"t":"電気又はガスの供給に関する行為","kind":"plain"}]},{"n":"四","s":[{"t":"運送に関する行為","kind":"plain"}]},{"n":"五","s":[{"t":"作業又は労務の請負","kind":"plain"}]},{"n":"六","s":[{"t":"出版、印刷又は撮影に関する行為","kind":"plain"}]},{"n":"七","s":[{"t":"客の来集を目的とする場屋における取引","kind":"plain"}]},{"n":"八","s":[{"t":"両替その他の銀行取引","kind":"plain"}]},{"n":"九","s":[{"t":"保険","kind":"plain"}]},{"n":"十","s":[{"t":"寄託の引受け","kind":"plain"}]},{"n":"十一","s":[{"t":"仲立ち又は取次ぎに関する行為","kind":"plain"}]},{"n":"十二","s":[{"t":"商行為の代理の引受け","kind":"plain"}]},{"n":"十三","s":[{"t":"信託の引受け","kind":"plain"}]}]}],"proviso":true,"deleted":false,"h":"71f86e7aee28"},{"num":"503","title":"第五百三条","caption":"（附属的商行為）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商人がその営業のためにする行為は、商行為とする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"商人の行為は、その営業のためにするものと推定する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7a4735712022"},{"num":"504","title":"第五百四条","caption":"（商行為の代理）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商行為の代理人が本人のためにすることを示さないでこれをした場合であっても、その行為は、本人に対してその効力を生ずる。","kind":"main"},{"t":"ただし、相手方が、代理人が本人のためにすることを知らなかったときは、代理人に対して履行の請求をすることを妨げない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"728393ec5ade"},{"num":"505","title":"第五百五条","caption":"（商行為の委任）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商行為の受任者は、委任の本旨に反しない範囲内において、委任を受けていない行為をすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"99e1280209c9"},{"num":"506","title":"第五百六条","caption":"（商行為の委任による代理権の消滅事由の特例）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商行為の委任による代理権は、本人の死亡によっては、消滅しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5eec0c7f9975"},{"num":"507","title":"第五百七条","caption":"","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"508","title":"第五百八条","caption":"（隔地者間における契約の申込み）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商人である隔地者の間において承諾の期間を定めないで契約の申込みを受けた者が相当の期間内に承諾の通知を発しなかったときは、その申込みは、その効力を失う。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"民法第五百二十四条の規定は、前項の場合について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"01b95bbace15"},{"num":"509","title":"第五百九条","caption":"（契約の申込みを受けた者の諾否通知義務）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商人が平常取引をする者からその営業の部類に属する契約の申込みを受けたときは、遅滞なく、契約の申込みに対する諾否の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"商人が前項の通知を発することを怠ったときは、その商人は、同項の契約の申込みを承諾したものとみなす。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b6760803bd72"},{"num":"510","title":"第五百十条","caption":"（契約の申込みを受けた者の物品保管義務）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商人がその営業の部類に属する契約の申込みを受けた場合において、その申込みとともに受け取った物品があるときは、その申込みを拒絶したときであっても、申込者の費用をもってその物品を保管しなければならない。","kind":"main"},{"t":"ただし、その物品の価額がその費用を償うのに足りないとき、又は商人がその保管によって損害を受けるときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"1d7b16d0926d"},{"num":"511","title":"第五百十一条","caption":"（多数当事者間の債務の連帯）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"数人の者がその一人又は全員のために商行為となる行為によって債務を負担したときは、その債務は、各自が連帯して負担する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"保証人がある場合において、債務が主たる債務者の商行為によって生じたものであるとき、又は保証が商行為であるときは、主たる債務者及び保証人が各別の行為によって債務を負担したときであっても、その債務は、各自が連帯して負担する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"615019c7b59a"},{"num":"512","title":"第五百十二条","caption":"（報酬請求権）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商人がその営業の範囲内において他人のために行為をしたときは、相当な報酬を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"09247ec5f46b"},{"num":"513","title":"第五百十三条","caption":"（利息請求権）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商人間において金銭の消費貸借をしたときは、貸主は、法定利息を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"商人がその営業の範囲内において他人のために金銭の立替えをしたときは、その立替えの日以後の法定利息を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e7766285c789"},{"num":"514","title":"第五百十四条","caption":"","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"515","title":"第五百十五条","caption":"（契約による質物の処分の禁止の適用除外）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"民法第三百四十九条の規定は、商行為によって生じた債権を担保するために設定した質権については、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e2a9e9a1fb50"},{"num":"516","title":"第五百十六条","caption":"（債務の履行の場所）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商行為によって生じた債務の履行をすべき場所がその行為の性質又は当事者の意思表示によって定まらないときは、特定物の引渡しはその行為の時にその物が存在した場所において、その他の債務の履行は債権者の現在の営業所（営業所がない場合にあっては、その住所）において、それぞれしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"81dc669fc68c"},{"num":"517:520","title":"第五百十七条から第五百二十条まで","caption":"","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"521","title":"第五百二十一条","caption":"（商人間の留置権）","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"商人間においてその双方のために商行為となる行為によって生じた債権が弁済期にあるときは、債権者は、その債権の弁済を受けるまで、その債務者との間における商行為によって自己の占有に属した債務者の所有する物又は有価証券を留置することができる。","kind":"main"},{"t":"ただし、当事者の別段の意思表示があるときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"60c25c513777"},{"num":"522:523","title":"第五百二十二条及び第五百二十三条","caption":"","path":["第二編　商行為","第一章　総則"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"524","title":"第五百二十四条","caption":"（売主による目的物の供託及び競売）","path":["第二編　商行為","第二章　売買"],"paras":[{"n":"1","s":[{"t":"商人間の売買において、買主がその目的物の受領を拒み、又はこれを受領することができないときは、売主は、その物を供託し、又は相当の期間を定めて催告をした後に競売に付することができる。","kind":"plain"},{"t":"この場合において、売主がその物を供託し、又は競売に付したときは、遅滞なく、買主に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"損傷その他の事由による価格の低落のおそれがある物は、前項の催告をしないで競売に付することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定により売買の目的物を競売に付したときは、売主は、その代価を供託しなければならない。","kind":"main"},{"t":"ただし、その代価の全部又は一部を代金に充当することを妨げない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"107d6d4b8690"},{"num":"525","title":"第五百二十五条","caption":"（定期売買の履行遅滞による解除）","path":["第二編　商行為","第二章　売買"],"paras":[{"n":"1","s":[{"t":"商人間の売買において、売買の性質又は当事者の意思表示により、特定の日時又は一定の期間内に履行をしなければ契約をした目的を達することができない場合において、当事者の一方が履行をしないでその時期を経過したときは、相手方は、直ちにその履行の請求をした場合を除き、契約の解除をしたものとみなす。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"8dbbe6707230"},{"num":"526","title":"第五百二十六条","caption":"（買主による目的物の検査及び通知）","path":["第二編　商行為","第二章　売買"],"paras":[{"n":"1","s":[{"t":"商人間の売買において、買主は、その売買の目的物を受領したときは、遅滞なく、その物を検査しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項に規定する場合において、買主は、同項の規定による検査により売買の目的物が種類、品質又は数量に関して契約の内容に適合しないことを発見したときは、直ちに売主に対してその旨の通知を発しなければ、その不適合を理由とする履行の追完の請求、代金の減額の請求、損害賠償の請求及び契約の解除をすることができない。","kind":"plain"},{"t":"売買の目的物が種類又は品質に関して契約の内容に適合しないことを直ちに発見することができない場合において、買主が六箇月以内にその不適合を発見したときも、同様とする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前項の規定は、売買の目的物が種類、品質又は数量に関して契約の内容に適合しないことにつき売主が悪意であった場合には、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"37fa92f159c7"},{"num":"527","title":"第五百二十七条","caption":"（買主による目的物の保管及び供託）","path":["第二編　商行為","第二章　売買"],"paras":[{"n":"1","s":[{"t":"前条第一項に規定する場合においては、買主は、契約の解除をしたときであっても、売主の費用をもって売買の目的物を保管し、又は供託しなければならない。","kind":"main"},{"t":"ただし、その物について滅失又は損傷のおそれがあるときは、裁判所の許可を得てその物を競売に付し、かつ、その代価を保管し、又は供託しなければならない。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"前項ただし書の許可に係る事件は、同項の売買の目的物の所在地を管轄する地方裁判所が管轄する。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項の規定により買主が売買の目的物を競売に付したときは、遅滞なく、売主に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前三項の規定は、売主及び買主の営業所（営業所がない場合にあっては、その住所）が同一の市町村の区域内にある場合には、適用しない。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"d35d8b76ae58"},{"num":"528","title":"第五百二十八条","caption":"","path":["第二編　商行為","第二章　売買"],"paras":[{"n":"1","s":[{"t":"前条の規定は、売主から買主に引き渡した物品が注文した物品と異なる場合における当該売主から買主に引き渡した物品及び売主から買主に引き渡した物品の数量が注文した数量を超過した場合における当該超過した部分の数量の物品について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"cb42ce6a276a"},{"num":"529","title":"第五百二十九条","caption":"（交互計算）","path":["第二編　商行為","第三章　交互計算"],"paras":[{"n":"1","s":[{"t":"交互計算は、商人間又は商人と商人でない者との間で平常取引をする場合において、一定の期間内の取引から生ずる債権及び債務の総額について相殺をし、その残額の支払をすることを約することによって、その効力を生ずる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"1bb5a97a7905"},{"num":"530","title":"第五百三十条","caption":"（商業証券に係る債権債務に関する特則）","path":["第二編　商行為","第三章　交互計算"],"paras":[{"n":"1","s":[{"t":"手形その他の商業証券から生じた債権及び債務を交互計算に組み入れた場合において、その商業証券の債務者が弁済をしないときは、当事者は、その債務に関する項目を交互計算から除外することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"36af3b0054e4"},{"num":"531","title":"第五百三十一条","caption":"（交互計算の期間）","path":["第二編　商行為","第三章　交互計算"],"paras":[{"n":"1","s":[{"t":"当事者が相殺をすべき期間を定めなかったときは、その期間は、六箇月とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b0f07f136b55"},{"num":"532","title":"第五百三十二条","caption":"（交互計算の承認）","path":["第二編　商行為","第三章　交互計算"],"paras":[{"n":"1","s":[{"t":"当事者は、債権及び債務の各項目を記載した計算書の承認をしたときは、当該各項目について異議を述べることができない。","kind":"main"},{"t":"ただし、当該計算書の記載に錯誤又は脱漏があったときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"4164d7b4abdb"},{"num":"533","title":"第五百三十三条","caption":"（残額についての利息請求権等）","path":["第二編　商行為","第三章　交互計算"],"paras":[{"n":"1","s":[{"t":"相殺によって生じた残額については、債権者は、計算の閉鎖の日以後の法定利息を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、当該相殺に係る債権及び債務の各項目を交互計算に組み入れた日からこれに利息を付することを妨げない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"80ccdbe09a69"},{"num":"534","title":"第五百三十四条","caption":"（交互計算の解除）","path":["第二編　商行為","第三章　交互計算"],"paras":[{"n":"1","s":[{"t":"各当事者は、いつでも交互計算の解除をすることができる。","kind":"plain"},{"t":"この場合において、交互計算の解除をしたときは、直ちに、計算を閉鎖して、残額の支払を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5832bd114799"},{"num":"535","title":"第五百三十五条","caption":"（匿名組合契約）","path":["第二編　商行為","第四章　匿名組合"],"paras":[{"n":"1","s":[{"t":"匿名組合契約は、当事者の一方が相手方の営業のために出資をし、その営業から生ずる利益を分配することを約することによって、その効力を生ずる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"1de25ff4976f"},{"num":"536","title":"第五百三十六条","caption":"（匿名組合員の出資及び権利義務）","path":["第二編　商行為","第四章　匿名組合"],"paras":[{"n":"1","s":[{"t":"匿名組合員の出資は、営業者の財産に属する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"匿名組合員は、金銭その他の財産のみをその出資の目的とすることができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"匿名組合員は、営業者の業務を執行し、又は営業者を代表することができない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"匿名組合員は、営業者の行為について、第三者に対して権利及び義務を有しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"09a7e2d87ed1"},{"num":"537","title":"第五百三十七条","caption":"（自己の氏名等の使用を許諾した匿名組合員の責任）","path":["第二編　商行為","第四章　匿名組合"],"paras":[{"n":"1","s":[{"t":"匿名組合員は、自己の氏若しくは氏名を営業者の商号中に用いること又は自己の商号を営業者の商号として使用することを許諾したときは、その使用以後に生じた債務については、営業者と連帯してこれを弁済する責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e721ac563e83"},{"num":"538","title":"第五百三十八条","caption":"（利益の配当の制限）","path":["第二編　商行為","第四章　匿名組合"],"paras":[{"n":"1","s":[{"t":"出資が損失によって減少したときは、その損失をてん補した後でなければ、匿名組合員は、利益の配当を請求することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b08e089617c0"},{"num":"539","title":"第五百三十九条","caption":"（貸借対照表の閲覧等並びに業務及び財産状況に関する検査）","path":["第二編　商行為","第四章　匿名組合"],"paras":[{"n":"1","s":[{"t":"匿名組合員は、営業年度の終了時において、営業者の営業時間内に、次に掲げる請求をし、又は営業者の業務及び財産の状況を検査することができる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"営業者の貸借対照表が書面をもって作成されているときは、当該書面の閲覧又は謄写の請求","kind":"plain"}]},{"n":"二","s":[{"t":"営業者の貸借対照表が電磁的記録（電子的方式、磁気的方式その他人の知覚によっては認識することができない方式で作られる記録であって、電子計算機による情報処理の用に供されるもので法務省令で定めるものをいう。）をもって作成されているときは、当該電磁的記録に記録された事項を法務省令で定める方法により表示したものの閲覧又は謄写の請求","kind":"plain"}]}]},{"n":"２","s":[{"t":"匿名組合員は、重要な事由があるときは、いつでも、裁判所の許可を得て、営業者の業務及び財産の状況を検査することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前項の許可に係る事件は、営業者の営業所の所在地（営業所がない場合にあっては、営業者の住所地）を管轄する地方裁判所が管轄する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"608e807b1f46"},{"num":"540","title":"第五百四十条","caption":"（匿名組合契約の解除）","path":["第二編　商行為","第四章　匿名組合"],"paras":[{"n":"1","s":[{"t":"匿名組合契約で匿名組合の存続期間を定めなかったとき、又はある当事者の終身の間匿名組合が存続すべきことを定めたときは、各当事者は、営業年度の終了時において、契約の解除をすることができる。","kind":"main"},{"t":"ただし、六箇月前にその予告をしなければならない。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"匿名組合の存続期間を定めたか否かにかかわらず、やむを得ない事由があるときは、各当事者は、いつでも匿名組合契約の解除をすることができる。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"db0d5055d4e3"},{"num":"541","title":"第五百四十一条","caption":"（匿名組合契約の終了事由）","path":["第二編　商行為","第四章　匿名組合"],"paras":[{"n":"1","s":[{"t":"前条の場合のほか、匿名組合契約は、次に掲げる事由によって終了する。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"匿名組合の目的である事業の成功又はその成功の不能","kind":"plain"}]},{"n":"二","s":[{"t":"営業者の死亡又は営業者が後見開始の審判を受けたこと。","kind":"plain"}]},{"n":"三","s":[{"t":"営業者又は匿名組合員が破産手続開始の決定を受けたこと。","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"63d1d9c0813d"},{"num":"542","title":"第五百四十二条","caption":"（匿名組合契約の終了に伴う出資の価額の返還）","path":["第二編　商行為","第四章　匿名組合"],"paras":[{"n":"1","s":[{"t":"匿名組合契約が終了したときは、営業者は、匿名組合員にその出資の価額を返還しなければならない。","kind":"main"},{"t":"ただし、出資が損失によって減少したときは、その残額を返還すれば足りる。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"de38af42a1b8"},{"num":"543","title":"第五百四十三条","caption":"（定義）","path":["第二編　商行為","第五章　仲立営業"],"paras":[{"n":"1","s":[{"t":"この章において「仲立人」とは、他人間の商行為の媒介をすることを業とする者をいう。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f67d4bf919a3"},{"num":"544","title":"第五百四十四条","caption":"（当事者のために給付を受けることの制限）","path":["第二編　商行為","第五章　仲立営業"],"paras":[{"n":"1","s":[{"t":"仲立人は、その媒介により成立させた行為について、当事者のために支払その他の給付を受けることができない。","kind":"main"},{"t":"ただし、当事者の別段の意思表示又は別段の慣習があるときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"280ebcee9172"},{"num":"545","title":"第五百四十五条","caption":"（見本保管義務）","path":["第二編　商行為","第五章　仲立営業"],"paras":[{"n":"1","s":[{"t":"仲立人がその媒介に係る行為について見本を受け取ったときは、その行為が完了するまで、これを保管しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"55c6f779b7ab"},{"num":"546","title":"第五百四十六条","caption":"（結約書の交付義務等）","path":["第二編　商行為","第五章　仲立営業"],"paras":[{"n":"1","s":[{"t":"当事者間において媒介に係る行為が成立したときは、仲立人は、遅滞なく、次に掲げる事項を記載した書面（以下この章において「結約書」という。）を作成し、かつ、署名し、又は記名押印した後、これを各当事者に交付しなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"各当事者の氏名又は名称","kind":"plain"}]},{"n":"二","s":[{"t":"当該行為の年月日及びその要領","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項の場合においては、当事者が直ちに履行をすべきときを除き、仲立人は、各当事者に結約書に署名させ、又は記名押印させた後、これをその相手方に交付しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の場合において、当事者の一方が結約書を受領せず、又はこれに署名若しくは記名押印をしないときは、仲立人は、遅滞なく、相手方に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"1902bdfb8637"},{"num":"547","title":"第五百四十七条","caption":"（帳簿記載義務等）","path":["第二編　商行為","第五章　仲立営業"],"paras":[{"n":"1","s":[{"t":"仲立人は、その帳簿に前条第一項各号に掲げる事項を記載しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"当事者は、いつでも、仲立人がその媒介により当該当事者のために成立させた行為について、前項の帳簿の謄本の交付を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"dc2105b2d050"},{"num":"548","title":"第五百四十八条","caption":"（当事者の氏名等を相手方に示さない場合）","path":["第二編　商行為","第五章　仲立営業"],"paras":[{"n":"1","s":[{"t":"当事者がその氏名又は名称を相手方に示してはならない旨を仲立人に命じたときは、仲立人は、結約書及び前条第二項の謄本にその氏名又は名称を記載することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5ff73d555c38"},{"num":"549","title":"第五百四十九条","caption":"","path":["第二編　商行為","第五章　仲立営業"],"paras":[{"n":"1","s":[{"t":"仲立人は、当事者の一方の氏名又は名称をその相手方に示さなかったときは、当該相手方に対して自ら履行をする責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a0459f6060de"},{"num":"550","title":"第五百五十条","caption":"（仲立人の報酬）","path":["第二編　商行為","第五章　仲立営業"],"paras":[{"n":"1","s":[{"t":"仲立人は、第五百四十六条の手続を終了した後でなければ、報酬を請求することができない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"仲立人の報酬は、当事者双方が等しい割合で負担する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d3eab55ad73c"},{"num":"551","title":"第五百五十一条","caption":"（定義）","path":["第二編　商行為","第六章　問屋営業"],"paras":[{"n":"1","s":[{"t":"この章において「問屋」とは、自己の名をもって他人のために物品の販売又は買入れをすることを業とする者をいう。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e187d47a9875"},{"num":"552","title":"第五百五十二条","caption":"（問屋の権利義務）","path":["第二編　商行為","第六章　問屋営業"],"paras":[{"n":"1","s":[{"t":"問屋は、他人のためにした販売又は買入れにより、相手方に対して、自ら権利を取得し、義務を負う。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"問屋と委託者との間の関係については、この章に定めるもののほか、委任及び代理に関する規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d5c542775937"},{"num":"553","title":"第五百五十三条","caption":"（問屋の担保責任）","path":["第二編　商行為","第六章　問屋営業"],"paras":[{"n":"1","s":[{"t":"問屋は、委託者のためにした販売又は買入れにつき相手方がその債務を履行しないときに、自らその履行をする責任を負う。","kind":"main"},{"t":"ただし、当事者の別段の意思表示又は別段の慣習があるときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"06d81e42fd76"},{"num":"554","title":"第五百五十四条","caption":"（問屋が委託者の指定した金額との差額を負担する場合の販売又は買入れの効力）","path":["第二編　商行為","第六章　問屋営業"],"paras":[{"n":"1","s":[{"t":"問屋が委託者の指定した金額より低い価格で販売をし、又は高い価格で買入れをした場合において、自らその差額を負担するときは、その販売又は買入れは、委託者に対してその効力を生ずる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"533050e15685"},{"num":"555","title":"第五百五十五条","caption":"（介入権）","path":["第二編　商行為","第六章　問屋営業"],"paras":[{"n":"1","s":[{"t":"問屋は、取引所の相場がある物品の販売又は買入れの委託を受けたときは、自ら買主又は売主となることができる。","kind":"plain"},{"t":"この場合において、売買の代価は、問屋が買主又は売主となったことの通知を発した時における取引所の相場によって定める。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の場合においても、問屋は、委託者に対して報酬を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"868647f42ebf"},{"num":"556","title":"第五百五十六条","caption":"（問屋が買い入れた物品の供託及び競売）","path":["第二編　商行為","第六章　問屋営業"],"paras":[{"n":"1","s":[{"t":"問屋が買入れの委託を受けた場合において、委託者が買い入れた物品の受領を拒み、又はこれを受領することができないときは、第五百二十四条の規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"00934b47aef3"},{"num":"557","title":"第五百五十七条","caption":"（代理商に関する規定の準用）","path":["第二編　商行為","第六章　問屋営業"],"paras":[{"n":"1","s":[{"t":"第二十七条及び第三十一条の規定は、問屋について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"96551e5e1126"},{"num":"558","title":"第五百五十八条","caption":"（準問屋）","path":["第二編　商行為","第六章　問屋営業"],"paras":[{"n":"1","s":[{"t":"この章の規定は、自己の名をもって他人のために販売又は買入れ以外の行為をすることを業とする者について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"72f23dab1d24"},{"num":"559","title":"第五百五十九条","caption":"（定義等）","path":["第二編　商行為","第七章　運送取扱営業"],"paras":[{"n":"1","s":[{"t":"この章において「運送取扱人」とは、自己の名をもって物品運送の取次ぎをすることを業とする者をいう。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"運送取扱人については、この章に別段の定めがある場合を除き、第五百五十一条に規定する問屋に関する規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e08ed675b8b7"},{"num":"560","title":"第五百六十条","caption":"（運送取扱人の責任）","path":["第二編　商行為","第七章　運送取扱営業"],"paras":[{"n":"1","s":[{"t":"運送取扱人は、運送品の受取から荷受人への引渡しまでの間にその運送品が滅失し若しくは損傷し、若しくはその滅失若しくは損傷の原因が生じ、又は運送品が延着したときは、これによって生じた損害を賠償する責任を負う。","kind":"main"},{"t":"ただし、運送取扱人がその運送品の受取、保管及び引渡し、運送人の選択その他の運送の取次ぎについて注意を怠らなかったことを証明したときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"b5579fa6f052"},{"num":"561","title":"第五百六十一条","caption":"（運送取扱人の報酬）","path":["第二編　商行為","第七章　運送取扱営業"],"paras":[{"n":"1","s":[{"t":"運送取扱人は、運送品を運送人に引き渡したときは、直ちにその報酬を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"運送取扱契約で運送賃の額を定めたときは、運送取扱人は、特約がなければ、別に報酬を請求することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"72eecf6e21ff"},{"num":"562","title":"第五百六十二条","caption":"（運送取扱人の留置権）","path":["第二編　商行為","第七章　運送取扱営業"],"paras":[{"n":"1","s":[{"t":"運送取扱人は、運送品に関して受け取るべき報酬、付随の費用及び運送賃その他の立替金についてのみ、その弁済を受けるまで、その運送品を留置することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"66e9ca47ad5e"},{"num":"563","title":"第五百六十三条","caption":"（介入権）","path":["第二編　商行為","第七章　運送取扱営業"],"paras":[{"n":"1","s":[{"t":"運送取扱人は、自ら運送をすることができる。","kind":"plain"},{"t":"この場合において、運送取扱人は、運送人と同一の権利義務を有する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"運送取扱人が委託者の請求によって船荷証券又は複合運送証券を作成したときは、自ら運送をするものとみなす。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"02440c97bef3"},{"num":"564","title":"第五百六十四条","caption":"（物品運送に関する規定の準用）","path":["第二編　商行為","第七章　運送取扱営業"],"paras":[{"n":"1","s":[{"t":"第五百七十二条、第五百七十七条、第五百七十九条（第三項を除く。）、第五百八十一条、第五百八十五条、第五百八十六条、第五百八十七条（第五百七十七条及び第五百八十五条の規定の準用に係る部分に限る。）及び第五百八十八条の規定は、運送取扱営業について準用する。","kind":"plain"},{"t":"この場合において、第五百七十九条第二項中「前の運送人」とあるのは「前の運送取扱人又は運送人」と、第五百八十五条第一項中「運送品の引渡し」とあるのは「荷受人に対する運送品の引渡し」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"4c308f6f083e"},{"num":"565:568","title":"第五百六十五条から第五百六十八条まで","caption":"","path":["第二編　商行為","第七章　運送取扱営業"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"569","title":"第五百六十九条","caption":"","path":["第二編　商行為","第八章　運送営業","第一節　総則"],"paras":[{"n":"1","s":[{"t":"この法律において、次の各号に掲げる用語の意義は、当該各号に定めるところによる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"運送人：陸上運送、海上運送又は航空運送の引受けをすることを業とする者をいう。","kind":"plain"}]},{"n":"二","s":[{"t":"陸上運送：陸上における物品又は旅客の運送をいう。","kind":"plain"}]},{"n":"三","s":[{"t":"海上運送：第六百八十四条に規定する船舶（第七百四十七条に規定する非航海船を含む。）による物品又は旅客の運送をいう。","kind":"plain"}]},{"n":"四","s":[{"t":"航空運送：航空法（昭和二十七年法律第二百三十一号）第二条第一項に規定する航空機による物品又は旅客の運送をいう。","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"f5ffd5a76eae"},{"num":"570","title":"第五百七十条","caption":"（物品運送契約）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"物品運送契約は、運送人が荷送人からある物品を受け取りこれを運送して荷受人に引き渡すことを約し、荷送人がその結果に対してその運送賃を支払うことを約することによって、その効力を生ずる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"8a0b33aa29c1"},{"num":"571","title":"第五百七十一条","caption":"（送り状の交付義務等）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"荷送人は、運送人の請求により、次に掲げる事項を記載した書面（次項において「送り状」という。）を交付しなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"運送品の種類","kind":"plain"}]},{"n":"二","s":[{"t":"運送品の容積若しくは重量又は包若しくは個品の数及び運送品の記号","kind":"plain"}]},{"n":"三","s":[{"t":"荷造りの種類","kind":"plain"}]},{"n":"四","s":[{"t":"荷送人及び荷受人の氏名又は名称","kind":"plain"}]},{"n":"五","s":[{"t":"発送地及び到達地","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項の荷送人は、送り状の交付に代えて、法務省令で定めるところにより、運送人の承諾を得て、送り状に記載すべき事項を電磁的方法（電子情報処理組織を使用する方法その他の情報通信の技術を利用する方法であって法務省令で定めるものをいう。以下同じ。）により提供することができる。","kind":"plain"},{"t":"この場合において、当該荷送人は、送り状を交付したものとみなす。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2f4b4fa73abc"},{"num":"572","title":"第五百七十二条","caption":"（危険物に関する通知義務）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"荷送人は、運送品が引火性、爆発性その他の危険性を有するものであるときは、その引渡しの前に、運送人に対し、その旨及び当該運送品の品名、性質その他の当該運送品の安全な運送に必要な情報を通知しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"8122bc53591f"},{"num":"573","title":"第五百七十三条","caption":"（運送賃）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"運送賃は、到達地における運送品の引渡しと同時に、支払わなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"運送品がその性質又は瑕疵によって滅失し、又は損傷したときは、荷送人は、運送賃の支払を拒むことができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"88f5cf11b8a8"},{"num":"574","title":"第五百七十四条","caption":"（運送人の留置権）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"運送人は、運送品に関して受け取るべき運送賃、付随の費用及び立替金（以下この節において「運送賃等」という。）についてのみ、その弁済を受けるまで、その運送品を留置することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"43b991417a40"},{"num":"575","title":"第五百七十五条","caption":"（運送人の責任）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"運送人は、運送品の受取から引渡しまでの間にその運送品が滅失し若しくは損傷し、若しくはその滅失若しくは損傷の原因が生じ、又は運送品が延着したときは、これによって生じた損害を賠償する責任を負う。","kind":"main"},{"t":"ただし、運送人がその運送品の受取、運送、保管及び引渡しについて注意を怠らなかったことを証明したときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"d58122e99bc5"},{"num":"576","title":"第五百七十六条","caption":"（損害賠償の額）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"運送品の滅失又は損傷の場合における損害賠償の額は、その引渡しがされるべき地及び時における運送品の市場価格（取引所の相場がある物品については、その相場）によって定める。","kind":"main"},{"t":"ただし、市場価格がないときは、その地及び時における同種類で同一の品質の物品の正常な価格によって定める。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"運送品の滅失又は損傷のために支払うことを要しなくなった運送賃その他の費用は、前項の損害賠償の額から控除する。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定は、運送人の故意又は重大な過失によって運送品の滅失又は損傷が生じたときは、適用しない。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"cb29e1690e56"},{"num":"577","title":"第五百七十七条","caption":"（高価品の特則）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"貨幣、有価証券その他の高価品については、荷送人が運送を委託するに当たりその種類及び価額を通知した場合を除き、運送人は、その滅失、損傷又は延着について損害賠償の責任を負わない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、次に掲げる場合には、適用しない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"物品運送契約の締結の当時、運送品が高価品であることを運送人が知っていたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"運送人の故意又は重大な過失によって高価品の滅失、損傷又は延着が生じたとき。","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"3b672b92e949"},{"num":"578","title":"第五百七十八条","caption":"（複合運送人の責任）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"陸上運送、海上運送又は航空運送のうち二以上の運送を一の契約で引き受けた場合における運送品の滅失等（運送品の滅失、損傷又は延着をいう。以下この節において同じ。）についての運送人の損害賠償の責任は、それぞれの運送においてその運送品の滅失等の原因が生じた場合に当該運送ごとに適用されることとなる我が国の法令又は我が国が締結した条約の規定に従う。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、陸上運送であってその区間ごとに異なる二以上の法令が適用されるものを一の契約で引き受けた場合について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"363106d93b2a"},{"num":"579","title":"第五百七十九条","caption":"（相次運送人の権利義務）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"数人の運送人が相次いで陸上運送をするときは、後の運送人は、前の運送人に代わってその権利を行使する義務を負う。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の場合において、後の運送人が前の運送人に弁済をしたときは、後の運送人は、前の運送人の権利を取得する。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"ある運送人が引き受けた陸上運送についてその荷送人のために他の運送人が相次いで当該陸上運送の一部を引き受けたときは、各運送人は、運送品の滅失等につき連帯して損害賠償の責任を負う。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前三項の規定は、海上運送及び航空運送について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d1f350a065c7"},{"num":"580","title":"第五百八十条","caption":"（荷送人による運送の中止等の請求）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"荷送人は、運送人に対し、運送の中止、荷受人の変更その他の処分を請求することができる。","kind":"plain"},{"t":"この場合において、運送人は、既にした運送の割合に応じた運送賃、付随の費用、立替金及びその処分によって生じた費用の弁済を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"954e8c5a1730"},{"num":"581","title":"第五百八十一条","caption":"（荷受人の権利義務等）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"荷受人は、運送品が到達地に到着し、又は運送品の全部が滅失したときは、物品運送契約によって生じた荷送人の権利と同一の権利を取得する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の場合において、荷受人が運送品の引渡し又はその損害賠償の請求をしたときは、荷送人は、その権利を行使することができない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"荷受人は、運送品を受け取ったときは、運送人に対し、運送賃等を支払う義務を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"46c8d04f9f05"},{"num":"582","title":"第五百八十二条","caption":"（運送品の供託及び競売）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"運送人は、荷受人を確知することができないときは、運送品を供託することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項に規定する場合において、運送人が荷送人に対し相当の期間を定めて運送品の処分につき指図をすべき旨を催告したにもかかわらず、荷送人がその指図をしないときは、運送人は、その運送品を競売に付することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"損傷その他の事由による価格の低落のおそれがある運送品は、前項の催告をしないで競売に付することができる。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前二項の規定により運送品を競売に付したときは、運送人は、その代価を供託しなければならない。","kind":"main"},{"t":"ただし、その代価の全部又は一部を運送賃等に充当することを妨げない。","kind":"proviso"}],"items":[]},{"n":"５","s":[{"t":"運送人は、第一項から第三項までの規定により運送品を供託し、又は競売に付したときは、遅滞なく、荷送人に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"ddb88b321304"},{"num":"583","title":"第五百八十三条","caption":"","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"前条の規定は、荷受人が運送品の受取を拒み、又はこれを受け取ることができない場合について準用する。","kind":"plain"},{"t":"この場合において、同条第二項中「運送人が」とあるのは「運送人が、荷受人に対し相当の期間を定めて運送品の受取を催告し、かつ、その期間の経過後に」と、同条第五項中「荷送人」とあるのは「荷送人及び荷受人」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ccffc88521ad"},{"num":"584","title":"第五百八十四条","caption":"（運送人の責任の消滅）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"運送品の損傷又は一部滅失についての運送人の責任は、荷受人が異議をとどめないで運送品を受け取ったときは、消滅する。","kind":"main"},{"t":"ただし、運送品に直ちに発見することができない損傷又は一部滅失があった場合において、荷受人が引渡しの日から二週間以内に運送人に対してその旨の通知を発したときは、この限りでない。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、運送品の引渡しの当時、運送人がその運送品に損傷又は一部滅失があることを知っていたときは、適用しない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"運送人が更に第三者に対して運送を委託した場合において、荷受人が第一項ただし書の期間内に運送人に対して同項ただし書の通知を発したときは、運送人に対する第三者の責任に係る同項ただし書の期間は、運送人が当該通知を受けた日から二週間を経過する日まで延長されたものとみなす。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"77eb739213c8"},{"num":"585","title":"第五百八十五条","caption":"","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"運送品の滅失等についての運送人の責任は、運送品の引渡しがされた日（運送品の全部滅失の場合にあっては、その引渡しがされるべき日）から一年以内に裁判上の請求がされないときは、消滅する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の期間は、運送品の滅失等による損害が発生した後に限り、合意により、延長することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"運送人が更に第三者に対して運送を委託した場合において、運送人が第一項の期間内に損害を賠償し又は裁判上の請求をされたときは、運送人に対する第三者の責任に係る同項の期間は、運送人が損害を賠償し又は裁判上の請求をされた日から三箇月を経過する日まで延長されたものとみなす。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c428eec36df7"},{"num":"586","title":"第五百八十六条","caption":"（運送人の債権の消滅時効）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"運送人の荷送人又は荷受人に対する債権は、これを行使することができる時から一年間行使しないときは、時効によって消滅する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"94d255aad883"},{"num":"587","title":"第五百八十七条","caption":"（運送人の不法行為責任）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"第五百七十六条、第五百七十七条、第五百八十四条及び第五百八十五条の規定は、運送品の滅失等についての運送人の荷送人又は荷受人に対する不法行為による損害賠償の責任について準用する。","kind":"main"},{"t":"ただし、荷受人があらかじめ荷送人の委託による運送を拒んでいたにもかかわらず荷送人から運送を引き受けた運送人の荷受人に対する責任については、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"64af18d86764"},{"num":"588","title":"第五百八十八条","caption":"（運送人の被用者の不法行為責任）","path":["第二編　商行為","第八章　運送営業","第二節　物品運送"],"paras":[{"n":"1","s":[{"t":"前条の規定により運送品の滅失等についての運送人の損害賠償の責任が免除され、又は軽減される場合には、その責任が免除され、又は軽減される限度において、その運送品の滅失等についての運送人の被用者の荷送人又は荷受人に対する不法行為による損害賠償の責任も、免除され、又は軽減される。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、運送人の被用者の故意又は重大な過失によって運送品の滅失等が生じたときは、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5dbf6044394f"},{"num":"589","title":"第五百八十九条","caption":"（旅客運送契約）","path":["第二編　商行為","第八章　運送営業","第三節　旅客運送"],"paras":[{"n":"1","s":[{"t":"旅客運送契約は、運送人が旅客を運送することを約し、相手方がその結果に対してその運送賃を支払うことを約することによって、その効力を生ずる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d5e87d4611e5"},{"num":"590","title":"第五百九十条","caption":"（運送人の責任）","path":["第二編　商行為","第八章　運送営業","第三節　旅客運送"],"paras":[{"n":"1","s":[{"t":"運送人は、旅客が運送のために受けた損害を賠償する責任を負う。","kind":"main"},{"t":"ただし、運送人が運送に関し注意を怠らなかったことを証明したときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"97f01439caeb"},{"num":"591","title":"第五百九十一条","caption":"（特約禁止）","path":["第二編　商行為","第八章　運送営業","第三節　旅客運送"],"paras":[{"n":"1","s":[{"t":"旅客の生命又は身体の侵害による運送人の損害賠償の責任（運送の遅延を主たる原因とするものを除く。）を免除し、又は軽減する特約は、無効とする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、次に掲げる場合には、適用しない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"大規模な火災、震災その他の災害が発生し、又は発生するおそれがある場合において運送を行うとき。","kind":"plain"}]},{"n":"二","s":[{"t":"運送に伴い通常生ずる振動その他の事情により生命又は身体に重大な危険が及ぶおそれがある者の運送を行うとき。","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"b3a8c8eb0f7a"},{"num":"592","title":"第五百九十二条","caption":"（引渡しを受けた手荷物に関する運送人の責任等）","path":["第二編　商行為","第八章　運送営業","第三節　旅客運送"],"paras":[{"n":"1","s":[{"t":"運送人は、旅客から引渡しを受けた手荷物については、運送賃を請求しないときであっても、物品運送契約における運送人と同一の責任を負う。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"運送人の被用者は、前項に規定する手荷物について、物品運送契約における運送人の被用者と同一の責任を負う。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項に規定する手荷物が到達地に到着した日から一週間以内に旅客がその引渡しを請求しないときは、運送人は、その手荷物を供託し、又は相当の期間を定めて催告をした後に競売に付することができる。","kind":"plain"},{"t":"この場合において、運送人がその手荷物を供託し、又は競売に付したときは、遅滞なく、旅客に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"損傷その他の事由による価格の低落のおそれがある手荷物は、前項の催告をしないで競売に付することができる。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"前二項の規定により手荷物を競売に付したときは、運送人は、その代価を供託しなければならない。","kind":"main"},{"t":"ただし、その代価の全部又は一部を運送賃に充当することを妨げない。","kind":"proviso"}],"items":[]},{"n":"６","s":[{"t":"旅客の住所又は居所が知れないときは、第三項の催告及び通知は、することを要しない。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"c23fc105d736"},{"num":"593","title":"第五百九十三条","caption":"（引渡しを受けていない手荷物に関する運送人の責任等）","path":["第二編　商行為","第八章　運送営業","第三節　旅客運送"],"paras":[{"n":"1","s":[{"t":"運送人は、旅客から引渡しを受けていない手荷物（身の回り品を含む。）の滅失又は損傷については、故意又は過失がある場合を除き、損害賠償の責任を負わない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"第五百七十六条第一項及び第三項、第五百八十四条第一項、第五百八十五条第一項及び第二項、第五百八十七条（第五百七十六条第一項及び第三項、第五百八十四条第一項並びに第五百八十五条第一項及び第二項の規定の準用に係る部分に限る。）並びに第五百八十八条の規定は、運送人が前項に規定する手荷物の滅失又は損傷に係る損害賠償の責任を負う場合について準用する。","kind":"plain"},{"t":"この場合において、第五百七十六条第一項中「その引渡しがされるべき」とあるのは「その運送が終了すべき」と、第五百八十四条第一項中「荷受人が異議をとどめないで運送品を受け取った」とあるのは「旅客が運送の終了の時までに異議をとどめなかった」と、「荷受人が引渡しの日」とあるのは「旅客が運送の終了の日」と、第五百八十五条第一項中「運送品の引渡しがされた日（運送品の全部滅失の場合にあっては、その引渡しがされるべき日）」とあるのは「運送の終了の日」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"3d86ef1e6844"},{"num":"594","title":"第五百九十四条","caption":"（運送人の債権の消滅時効）","path":["第二編　商行為","第八章　運送営業","第三節　旅客運送"],"paras":[{"n":"1","s":[{"t":"第五百八十六条の規定は、旅客運送について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7c902a30c1f3"},{"num":"595","title":"第五百九十五条","caption":"（受寄者の注意義務）","path":["第二編　商行為","第九章　寄託","第一節　総則"],"paras":[{"n":"1","s":[{"t":"商人がその営業の範囲内において寄託を受けた場合には、報酬を受けないときであっても、善良な管理者の注意をもって、寄託物を保管しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"4d41f1d917e3"},{"num":"596","title":"第五百九十六条","caption":"（場屋営業者の責任）","path":["第二編　商行為","第九章　寄託","第一節　総則"],"paras":[{"n":"1","s":[{"t":"旅館、飲食店、浴場その他の客の来集を目的とする場屋における取引をすることを業とする者（以下この節において「場屋営業者」という。）は、客から寄託を受けた物品の滅失又は損傷については、不可抗力によるものであったことを証明しなければ、損害賠償の責任を免れることができない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"客が寄託していない物品であっても、場屋の中に携帯した物品が、場屋営業者が注意を怠ったことによって滅失し、又は損傷したときは、場屋営業者は、損害賠償の責任を負う。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"客が場屋の中に携帯した物品につき責任を負わない旨を表示したときであっても、場屋営業者は、前二項の責任を免れることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"752806e12e40"},{"num":"597","title":"第五百九十七条","caption":"（高価品の特則）","path":["第二編　商行為","第九章　寄託","第一節　総則"],"paras":[{"n":"1","s":[{"t":"貨幣、有価証券その他の高価品については、客がその種類及び価額を通知してこれを場屋営業者に寄託した場合を除き、場屋営業者は、その滅失又は損傷によって生じた損害を賠償する責任を負わない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5fe66a8b4916"},{"num":"598","title":"第五百九十八条","caption":"（場屋営業者の責任に係る債権の消滅時効）","path":["第二編　商行為","第九章　寄託","第一節　総則"],"paras":[{"n":"1","s":[{"t":"前二条の場屋営業者の責任に係る債権は、場屋営業者が寄託を受けた物品を返還し、又は客が場屋の中に携帯した物品を持ち去った時（物品の全部滅失の場合にあっては、客が場屋を去った時）から一年間行使しないときは、時効によって消滅する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、場屋営業者が同項に規定する物品の滅失又は損傷につき悪意であった場合には、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"42f5b0763a36"},{"num":"599","title":"第五百九十九条","caption":"（定義）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"この節において「倉庫営業者」とは、他人のために物品を倉庫に保管することを業とする者をいう。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"adadda2b8b25"},{"num":"600","title":"第六百条","caption":"（倉荷証券の交付義務）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉庫営業者は、寄託者の請求により、寄託物の倉荷証券を交付しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f7848322bf12"},{"num":"601","title":"第六百一条","caption":"（倉荷証券の記載事項）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉荷証券には、次に掲げる事項及びその番号を記載し、倉庫営業者がこれに署名し、又は記名押印しなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"寄託物の種類、品質及び数量並びにその荷造りの種類、個数及び記号","kind":"plain"}]},{"n":"二","s":[{"t":"寄託者の氏名又は名称","kind":"plain"}]},{"n":"三","s":[{"t":"保管場所","kind":"plain"}]},{"n":"四","s":[{"t":"保管料","kind":"plain"}]},{"n":"五","s":[{"t":"保管期間を定めたときは、その期間","kind":"plain"}]},{"n":"六","s":[{"t":"寄託物を保険に付したときは、保険金額、保険期間及び保険者の氏名又は名称","kind":"plain"}]},{"n":"七","s":[{"t":"作成地及び作成の年月日","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"214a2c522221"},{"num":"602","title":"第六百二条","caption":"（帳簿記載義務）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉庫営業者は、倉荷証券を寄託者に交付したときは、その帳簿に次に掲げる事項を記載しなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"前条第一号、第二号及び第四号から第六号までに掲げる事項","kind":"plain"}]},{"n":"二","s":[{"t":"倉荷証券の番号及び作成の年月日","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"8eb1c8e57b36"},{"num":"603","title":"第六百三条","caption":"（寄託物の分割請求）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉荷証券の所持人は、倉庫営業者に対し、寄託物の分割及びその各部分に対する倉荷証券の交付を請求することができる。","kind":"plain"},{"t":"この場合において、所持人は、その所持する倉荷証券を倉庫営業者に返還しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定による寄託物の分割及び倉荷証券の交付に関する費用は、所持人が負担する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"3d6a1b41b645"},{"num":"604","title":"第六百四条","caption":"（倉荷証券の不実記載）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉庫営業者は、倉荷証券の記載が事実と異なることをもって善意の所持人に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"fd8900884064"},{"num":"605","title":"第六百五条","caption":"（寄託物に関する処分）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉荷証券が作成されたときは、寄託物に関する処分は、倉荷証券によってしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c4c195c1fd8a"},{"num":"606","title":"第六百六条","caption":"（倉荷証券の譲渡又は質入れ）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉荷証券は、記名式であるときであっても、裏書によって、譲渡し、又は質権の目的とすることができる。","kind":"main"},{"t":"ただし、倉荷証券に裏書を禁止する旨を記載したときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"b19b33d6aff9"},{"num":"607","title":"第六百七条","caption":"（倉荷証券の引渡しの効力）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉荷証券により寄託物を受け取ることができる者に倉荷証券を引き渡したときは、その引渡しは、寄託物について行使する権利の取得に関しては、寄託物の引渡しと同一の効力を有する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"647e388889c2"},{"num":"608","title":"第六百八条","caption":"（倉荷証券の再交付）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉荷証券の所持人は、その倉荷証券を喪失したときは、相当の担保を供して、その再交付を請求することができる。","kind":"plain"},{"t":"この場合において、倉庫営業者は、その旨を帳簿に記載しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2c4ca1052d95"},{"num":"609","title":"第六百九条","caption":"（寄託物の点検等）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"寄託者又は倉荷証券の所持人は、倉庫営業者の営業時間内は、いつでも、寄託物の点検若しくはその見本の提供を求め、又はその保存に必要な処分をすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f73141023ca6"},{"num":"610","title":"第六百十条","caption":"（倉庫営業者の責任）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉庫営業者は、寄託物の保管に関し注意を怠らなかったことを証明しなければ、その滅失又は損傷につき損害賠償の責任を免れることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"fe4662e8bdcc"},{"num":"611","title":"第六百十一条","caption":"（保管料等の支払時期）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉庫営業者は、寄託物の出庫の時以後でなければ、保管料及び立替金その他寄託物に関する費用（第六百十六条第一項において「保管料等」という。）の支払を請求することができない。","kind":"main"},{"t":"ただし、寄託物の一部を出庫するときは、出庫の割合に応じて、その支払を請求することができる。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"70aee9f488f5"},{"num":"612","title":"第六百十二条","caption":"（寄託物の返還の制限）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"当事者が寄託物の保管期間を定めなかったときは、倉庫営業者は、寄託物の入庫の日から六箇月を経過した後でなければ、その返還をすることができない。","kind":"main"},{"t":"ただし、やむを得ない事由があるときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"05fd9861814c"},{"num":"613","title":"第六百十三条","caption":"（倉荷証券が作成された場合における寄託物の返還請求）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉荷証券が作成されたときは、これと引換えでなければ、寄託物の返還を請求することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"8e5182466758"},{"num":"614","title":"第六百十四条","caption":"（倉荷証券を質入れした場合における寄託物の一部の返還請求）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"倉荷証券を質権の目的とした場合において、質権者の承諾があるときは、寄託者は、当該質権の被担保債権の弁済期前であっても、寄託物の一部の返還を請求することができる。","kind":"plain"},{"t":"この場合において、倉庫営業者は、返還した寄託物の種類、品質及び数量を倉荷証券に記載し、かつ、その旨を帳簿に記載しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"25902807fb54"},{"num":"615","title":"第六百十五条","caption":"（寄託物の供託及び競売）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"第五百二十四条第一項及び第二項の規定は、寄託者又は倉荷証券の所持人が寄託物の受領を拒み、又はこれを受領することができない場合について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"dfba1d402fc8"},{"num":"616","title":"第六百十六条","caption":"（倉庫営業者の責任の消滅）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"寄託物の損傷又は一部滅失についての倉庫営業者の責任は、寄託者又は倉荷証券の所持人が異議をとどめないで寄託物を受け取り、かつ、保管料等を支払ったときは、消滅する。","kind":"main"},{"t":"ただし、寄託物に直ちに発見することができない損傷又は一部滅失があった場合において、寄託者又は倉荷証券の所持人が引渡しの日から二週間以内に倉庫営業者に対してその旨の通知を発したときは、この限りでない。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、倉庫営業者が寄託物の損傷又は一部滅失につき悪意であった場合には、適用しない。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"c4c07e0f830d"},{"num":"617","title":"第六百十七条","caption":"（倉庫営業者の責任に係る債権の消滅時効）","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"寄託物の滅失又は損傷についての倉庫営業者の責任に係る債権は、寄託物の出庫の日から一年間行使しないときは、時効によって消滅する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の期間は、寄託物の全部滅失の場合においては、倉庫営業者が倉荷証券の所持人（倉荷証券を作成していないとき又は倉荷証券の所持人が知れないときは、寄託者）に対してその旨の通知を発した日から起算する。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定は、倉庫営業者が寄託物の滅失又は損傷につき悪意であった場合には、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"128b33aa63ed"},{"num":"618:683","title":"第六百十八条から第六百八十三条まで","caption":"","path":["第二編　商行為","第九章　寄託","第二節　倉庫営業"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"684","title":"第六百八十四条","caption":"（定義）","path":["第三編　海商","第一章　船舶","第一節　総則"],"paras":[{"n":"1","s":[{"t":"この編（第七百四十七条を除く。）において「船舶」とは、商行為をする目的で航海の用に供する船舶（端舟その他ろかいのみをもって運転し、又は主としてろかいをもって運転する舟を除く。）をいう。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e85a22d54960"},{"num":"685","title":"第六百八十五条","caption":"（従物の推定等）","path":["第三編　海商","第一章　船舶","第一節　総則"],"paras":[{"n":"1","s":[{"t":"船舶の属具目録に記載した物は、その従物と推定する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"属具目録の書式は、国土交通省令で定める。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"07f65c96e099"},{"num":"686","title":"第六百八十六条","caption":"（船舶の登記等）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第一款　総則"],"paras":[{"n":"1","s":[{"t":"船舶所有者は、船舶法（明治三十二年法律第四十六号）の定めるところに従い、登記をし、かつ、船舶国籍証書の交付を受けなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、総トン数二十トン未満の船舶については、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"608d9246ad3d"},{"num":"687","title":"第六百八十七条","caption":"（船舶所有権の移転の対抗要件）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第一款　総則"],"paras":[{"n":"1","s":[{"t":"船舶所有権の移転は、その登記をし、かつ、船舶国籍証書に記載しなければ、第三者に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ece116346e7a"},{"num":"688","title":"第六百八十八条","caption":"（航海中の船舶を譲渡した場合の損益の帰属）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第一款　総則"],"paras":[{"n":"1","s":[{"t":"航海中の船舶を譲渡したときは、その航海によって生ずる損益は、譲受人に帰属する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c9f516c2e5a7"},{"num":"689","title":"第六百八十九条","caption":"（航海中の船舶に対する差押え等の制限）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第一款　総則"],"paras":[{"n":"1","s":[{"t":"差押え及び仮差押えの執行（仮差押えの登記をする方法によるものを除く。）は、航海中の船舶（停泊中のものを除く。）に対してはすることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"8b02faa2f64c"},{"num":"690","title":"第六百九十条","caption":"（船舶所有者の責任）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第一款　総則"],"paras":[{"n":"1","s":[{"t":"船舶所有者は、船長その他の船員がその職務を行うについて故意又は過失によって他人に加えた損害を賠償する責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c13cb78cc7ea"},{"num":"691","title":"第六百九十一条","caption":"（社員の持分の売渡しの請求）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第一款　総則"],"paras":[{"n":"1","s":[{"t":"持分会社の業務を執行する社員の持分の移転により当該持分会社の所有する船舶が日本の国籍を喪失することとなるときは、他の業務を執行する社員は、相当の対価でその持分を売り渡すことを請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"25686f05b5e8"},{"num":"692","title":"第六百九十二条","caption":"（共有に係る船舶の利用）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶共有者の間においては、船舶の利用に関する事項は、各船舶共有者の持分の価格に従い、その過半数で決する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e9872ea086a1"},{"num":"693","title":"第六百九十三条","caption":"","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶共有者は、その持分の価格に応じ、船舶の利用に関する費用を負担しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d452fce76977"},{"num":"694","title":"第六百九十四条","caption":"（船舶共有者の持分買取請求）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶共有者が次に掲げる事項を決定したときは、その決定について異議のある船舶共有者は、他の船舶共有者に対し、相当の対価で自己の持分を買い取ることを請求することができる。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"新たな航海（船舶共有者の間で予定されていなかったものに限る。）をすること。","kind":"plain"}]},{"n":"二","s":[{"t":"船舶の大修繕をすること。","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項の規定による請求をしようとする者は、同項の決定の日（当該決定に加わらなかった場合にあっては、当該決定の通知を受けた日の翌日）から三日以内に、他の船舶共有者又は船舶管理人に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"fe07ccec4b83"},{"num":"695","title":"第六百九十五条","caption":"（船舶共有者の第三者に対する責任）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶共有者は、その持分の価格に応じ、船舶の利用について生じた債務を弁済する責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a01f1bb9ef1f"},{"num":"696","title":"第六百九十六条","caption":"（持分の譲渡）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶共有者の間に組合契約があるときであっても、各船舶共有者（船舶管理人であるものを除く。）は、他の船舶共有者の承諾を得ないで、その持分の全部又は一部を他人に譲渡することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船舶管理人である船舶共有者は、他の船舶共有者の全員の承諾を得なければ、その持分の全部又は一部を他人に譲渡することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"737c493d5882"},{"num":"697","title":"第六百九十七条","caption":"（船舶管理人）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶共有者は、船舶管理人を選任しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船舶共有者でない者を船舶管理人とするには、船舶共有者の全員の同意がなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"船舶共有者が船舶管理人を選任したときは、その登記をしなければならない。","kind":"plain"},{"t":"船舶管理人の代理権の消滅についても、同様とする。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"第九条の規定は、前項の規定による登記について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7279e54215e0"},{"num":"698","title":"第六百九十八条","caption":"（船舶管理人の代理権）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶管理人は、次に掲げる行為を除き、船舶共有者に代わって船舶の利用に関する一切の裁判上又は裁判外の行為をする権限を有する。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"船舶を賃貸し、又はこれについて抵当権を設定すること。","kind":"plain"}]},{"n":"二","s":[{"t":"船舶を保険に付すること。","kind":"plain"}]},{"n":"三","s":[{"t":"新たな航海（船舶共有者の間で予定されていなかったものに限る。）をすること。","kind":"plain"}]},{"n":"四","s":[{"t":"船舶の大修繕をすること。","kind":"plain"}]},{"n":"五","s":[{"t":"借財をすること。","kind":"plain"}]}]},{"n":"２","s":[{"t":"船舶管理人の代理権に加えた制限は、善意の第三者に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f4352c53bb26"},{"num":"699","title":"第六百九十九条","caption":"（船舶管理人の義務）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶管理人は、その職務に関する帳簿を備え、船舶の利用に関する一切の事項を記載しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船舶管理人は、一定の期間ごとに、船舶の利用に関する計算を行い、各船舶共有者の承認を求めなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f8f7b48bf765"},{"num":"700","title":"第七百条","caption":"（船舶共有者の持分の売渡しの請求等）","path":["第三編　海商","第一章　船舶","第二節　船舶の所有","第二款　船舶の共有"],"paras":[{"n":"1","s":[{"t":"船舶共有者の持分の移転又は国籍の喪失により船舶が日本の国籍を喪失することとなるときは、他の船舶共有者は、相当の対価でその持分を売り渡すことを請求し、又は競売に付することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"f04d0e0bd94d"},{"num":"701","title":"第七百一条","caption":"（船舶賃貸借の対抗力）","path":["第三編　海商","第一章　船舶","第三節　船舶賃貸借"],"paras":[{"n":"1","s":[{"t":"船舶の賃貸借は、これを登記したときは、その後その船舶について物権を取得した者に対しても、その効力を生ずる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"32c1bbb91967"},{"num":"702","title":"第七百二条","caption":"（船舶の賃借人による修繕）","path":["第三編　海商","第一章　船舶","第三節　船舶賃貸借"],"paras":[{"n":"1","s":[{"t":"船舶の賃借人であって商行為をする目的でその船舶を航海の用に供しているものは、その船舶を受け取った後にこれに生じた損傷があるときは、その利用に必要な修繕をする義務を負う。","kind":"main"},{"t":"ただし、その損傷が賃貸人の責めに帰すべき事由によるものであるときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"13f90a3a716b"},{"num":"703","title":"第七百三条","caption":"（船舶の賃借人の権利義務等）","path":["第三編　海商","第一章　船舶","第三節　船舶賃貸借"],"paras":[{"n":"1","s":[{"t":"前条に規定する船舶の賃借人は、その船舶の利用に関する事項については、第三者に対して、船舶所有者と同一の権利義務を有する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の場合において、その船舶の利用について生じた先取特権は、船舶所有者に対しても、その効力を生ずる。","kind":"main"},{"t":"ただし、船舶の賃借人によるその利用の態様が船舶所有者との契約に反することを先取特権者が知っていたときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"14b18c618b1e"},{"num":"704","title":"第七百四条","caption":"（定期傭船契約）","path":["第三編　海商","第一章　船舶","第四節　定期傭船"],"paras":[{"n":"1","s":[{"t":"定期傭船契約は、当事者の一方が艤装した船舶に船員を乗り組ませて当該船舶を一定の期間相手方の利用に供することを約し、相手方がこれに対してその傭船料を支払うことを約することによって、その効力を生ずる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7445ff3b2a9d"},{"num":"705","title":"第七百五条","caption":"（定期傭船者による指示）","path":["第三編　海商","第一章　船舶","第四節　定期傭船"],"paras":[{"n":"1","s":[{"t":"定期傭船者は、船長に対し、航路の決定その他の船舶の利用に関し必要な事項を指示することができる。","kind":"main"},{"t":"ただし、発航前の検査その他の航海の安全に関する事項については、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"0bcdd30fac1e"},{"num":"706","title":"第七百六条","caption":"（費用の負担）","path":["第三編　海商","第一章　船舶","第四節　定期傭船"],"paras":[{"n":"1","s":[{"t":"船舶の燃料、水先料、入港料その他船舶の利用に関する通常の費用は、定期傭船者の負担とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"92e8556fee0d"},{"num":"707","title":"第七百七条","caption":"（運送及び船舶賃貸借に関する規定の準用）","path":["第三編　海商","第一章　船舶","第四節　定期傭船"],"paras":[{"n":"1","s":[{"t":"第五百七十二条、第七百三十九条第一項並びに第七百四十条第一項及び第三項の規定は定期傭船契約に係る船舶により物品を運送する場合について、第七百三条第二項の規定は定期傭船者の船舶の利用について生ずる先取特権について、それぞれ準用する。","kind":"plain"},{"t":"この場合において、第七百三十九条第一項中「発航の当時」とあるのは、「各航海に係る発航の当時」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ffa4bb210e5e"},{"num":"708","title":"第七百八条","caption":"（船長の代理権）","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"船長は、船籍港外においては、次に掲げる行為を除き、船舶所有者に代わって航海のために必要な一切の裁判上又は裁判外の行為をする権限を有する。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"船舶について抵当権を設定すること。","kind":"plain"}]},{"n":"二","s":[{"t":"借財をすること。","kind":"plain"}]}]},{"n":"２","s":[{"t":"船長の代理権に加えた制限は、善意の第三者に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c8136b0a198e"},{"num":"709","title":"第七百九条","caption":"（船長による職務代行者の選任）","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"船長は、やむを得ない事由により自ら船舶を指揮することができない場合には、法令に別段の定めがあるときを除き、自己に代わって船長の職務を行うべき者を選任することができる。","kind":"plain"},{"t":"この場合において、船長は、船舶所有者に対してその選任についての責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"98b5de896b16"},{"num":"710","title":"第七百十条","caption":"（属具目録の備置き）","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"船長は、属具目録を船内に備え置かなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"eae57d33c56a"},{"num":"711","title":"第七百十一条","caption":"（船長による積荷の処分）","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"船長は、航海中に積荷の利害関係人の利益のため必要があるときは、利害関係人に代わり、最もその利益に適合する方法によって、その積荷の処分をしなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"積荷の利害関係人は、前項の処分によりその積荷について債務を負担したときは、当該債務に係る債権者にその積荷について有する権利を移転して、その責任を免れることができる。","kind":"main"},{"t":"ただし、利害関係人に過失があったときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"961755af7f3a"},{"num":"712","title":"第七百十二条","caption":"（航海継続のための積荷の使用）","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"船長は、航海を継続するため必要があるときは、積荷を航海の用に供することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"第五百七十六条第一項及び第二項の規定は、前項の場合において船舶所有者が支払うべき償金の額について準用する。","kind":"plain"},{"t":"この場合において、同条第一項中「引渡し」とあるのは、「陸揚げ」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6e9359acd276"},{"num":"713","title":"第七百十三条","caption":"（船長の責任）","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"船長は、海員がその職務を行うについて故意又は過失によって他人に加えた損害を賠償する責任を負う。","kind":"main"},{"t":"ただし、船長が海員の監督について注意を怠らなかったことを証明したときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"b5eabd5edceb"},{"num":"714","title":"第七百十四条","caption":"（船長の報告義務）","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"船長は、遅滞なく、航海に関する重要な事項を船舶所有者に報告しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"1b7469b8ab6a"},{"num":"715","title":"第七百十五条","caption":"（船長の解任）","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"船舶所有者は、いつでも、船長を解任することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定により解任された船長は、その解任について正当な理由がある場合を除き、船舶所有者に対し、解任によって生じた損害の賠償を請求することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"船長が船舶共有者である場合において、その意に反して解任されたときは、船長は、他の船舶共有者に対し、相当の対価で自己の持分を買い取ることを請求することができる。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"船長は、前項の規定による請求をしようとするときは、遅滞なく、他の船舶共有者又は船舶管理人に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"cdf3fe0b2a76"},{"num":"716:736","title":"第七百十六条から第七百三十六条まで","caption":"","path":["第三編　海商","第二章　船長"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"737","title":"第七百三十七条","caption":"（運送品の船積み等）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"運送人は、個品運送契約（個々の運送品を目的とする運送契約をいう。以下この節において同じ。）に基づいて荷送人から運送品を受け取ったときは、その船積み及び積付けをしなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"荷送人が運送品の引渡しを怠ったときは、船長は、直ちに発航することができる。","kind":"plain"},{"t":"この場合において、荷送人は、運送賃の全額（運送人がその運送品に代わる他の運送品について運送賃を得た場合にあっては、当該運送賃の額を控除した額）を支払わなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"3c8f42e281be"},{"num":"738","title":"第七百三十八条","caption":"（船長に対する必要書類の交付）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"荷送人は、船積期間内に、運送に必要な書類を船長に交付しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6be1cc349af3"},{"num":"739","title":"第七百三十九条","caption":"（航海に堪える能力に関する注意義務）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"運送人は、発航の当時次に掲げる事項を欠いたことにより生じた運送品の滅失、損傷又は延着について、損害賠償の責任を負う。","kind":"main"},{"t":"ただし、運送人がその当時当該事項について注意を怠らなかったことを証明したときは、この限りでない。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"船舶を航海に堪える状態に置くこと。","kind":"plain"}]},{"n":"二","s":[{"t":"船員の乗組み、船舶の艤装及び需品の補給を適切に行うこと。","kind":"plain"}]},{"n":"三","s":[{"t":"船倉、冷蔵室その他運送品を積み込む場所を運送品の受入れ、運送及び保存に適する状態に置くこと。","kind":"plain"}]}]},{"n":"２","s":[{"t":"前項の規定による運送人の損害賠償の責任を免除し、又は軽減する特約は、無効とする。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"d3401838c65d"},{"num":"740","title":"第七百四十条","caption":"（違法な船積品の陸揚げ等）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"法令に違反して又は個品運送契約によらないで船積みがされた運送品については、運送人は、いつでも、これを陸揚げすることができ、船舶又は積荷に危害を及ぼすおそれがあるときは、これを放棄することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"運送人は、前項に規定する運送品を運送したときは、船積みがされた地及び時における同種の運送品に係る運送賃の最高額を請求することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定は、運送人その他の利害関係人の荷送人に対する損害賠償の請求を妨げない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2d4902306619"},{"num":"741","title":"第七百四十一条","caption":"（荷受人の運送賃支払義務等）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"荷受人は、運送品を受け取ったときは、個品運送契約又は船荷証券の趣旨に従い、運送人に対し、次に掲げる金額の合計額（以下この節において「運送賃等」という。）を支払う義務を負う。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"運送賃、付随の費用及び立替金の額","kind":"plain"}]},{"n":"二","s":[{"t":"運送品の価格に応じて支払うべき救助料の額及び共同海損の分担額","kind":"plain"}]}]},{"n":"２","s":[{"t":"運送人は、運送賃等の支払を受けるまで、運送品を留置することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c1da57e138c0"},{"num":"742","title":"第七百四十二条","caption":"（運送品の競売）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"運送人は、荷受人に運送品を引き渡した後においても、運送賃等の支払を受けるため、その運送品を競売に付することができる。","kind":"main"},{"t":"ただし、第三者がその占有を取得したときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"bc6b680386be"},{"num":"743","title":"第七百四十三条","caption":"（荷送人による発航前の解除）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"発航前においては、荷送人は、運送賃の全額を支払って個品運送契約の解除をすることができる。","kind":"main"},{"t":"ただし、個品運送契約の解除によって運送人に生ずる損害の額が運送賃の全額を下回るときは、その損害を賠償すれば足りる。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、運送品の全部又は一部の船積みがされた場合には、他の荷送人及び傭船者の全員の同意を得たときに限り、適用する。","kind":"plain"},{"t":"この場合において、荷送人は、運送品の船積み及び陸揚げに要する費用を負担しなければならない。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"c51871701841"},{"num":"744","title":"第七百四十四条","caption":"","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"荷送人は、前条の規定により個品運送契約の解除をしたときであっても、運送人に対する付随の費用及び立替金の支払義務を免れることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d54c7e587c36"},{"num":"745","title":"第七百四十五条","caption":"（荷送人による発航後の解除）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"発航後においては、荷送人は、他の荷送人及び傭船者の全員の同意を得、かつ、運送賃等及び運送品の陸揚げによって生ずべき損害の額の合計額を支払い、又は相当の担保を供しなければ、個品運送契約の解除をすることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a1666c38028c"},{"num":"746","title":"第七百四十六条","caption":"（積荷を航海の用に供した場合の運送賃）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"運送人は、船長が第七百十二条第一項の規定により積荷を航海の用に供したときにおいても、運送賃の全額を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"999a81801b32"},{"num":"747","title":"第七百四十七条","caption":"（非航海船による物品運送への準用）","path":["第三編　海商","第三章　海上物品運送に関する特則","第一節　個品運送"],"paras":[{"n":"1","s":[{"t":"この節の規定は、商行為をする目的で専ら湖川、港湾その他の海以外の水域において航行の用に供する船舶（端舟その他ろかいのみをもって運転し、又は主としてろかいをもって運転する舟を除く。以下この編において「非航海船」という。）によって物品を運送する場合について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d491cc96c197"},{"num":"748","title":"第七百四十八条","caption":"（運送品の船積み）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"航海傭船契約（船舶の全部又は一部を目的とする運送契約をいう。以下この節において同じ。）に基づいて運送品の船積みのために必要な準備を完了したときは、船長は、遅滞なく、傭船者に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船積期間の定めがある航海傭船契約において始期を定めなかったときは、その期間は、前項の通知があった時から起算する。","kind":"plain"},{"t":"この場合において、不可抗力によって船積みをすることができない期間は、船積期間に算入しない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"傭船者が船積期間の経過後に運送品の船積みをした場合には、運送人は、特約がないときであっても、相当な滞船料を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"edb069f491dd"},{"num":"749","title":"第七百四十九条","caption":"（第三者による船積み）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"船長は、第三者から運送品を受け取るべき場合において、その第三者を確知することができないとき、又はその第三者が運送品の船積みをしないときは、直ちに傭船者に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の場合において、傭船者は、船積期間内に限り、運送品の船積みをすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"219b78eed314"},{"num":"750","title":"第七百五十条","caption":"（傭船者による発航の請求）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"傭船者は、運送品の全部の船積みをしていないときであっても、船長に対し、発航の請求をすることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"傭船者は、前項の請求をしたときは、運送人に対し、運送賃の全額のほか、運送品の全部の船積みをしないことによって生じた費用を支払う義務を負い、かつ、その請求により、当該費用の支払について相当の担保を供しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b9fe197a58fe"},{"num":"751","title":"第七百五十一条","caption":"（船長の発航権）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"船長は、船積期間が経過した後は、傭船者が運送品の全部の船積みをしていないときであっても、直ちに発航することができる。","kind":"plain"},{"t":"この場合においては、前条第二項の規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c561f4e8de70"},{"num":"752","title":"第七百五十二条","caption":"（運送品の陸揚げ）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"運送品の陸揚げのために必要な準備を完了したときは、船長は、遅滞なく、荷受人に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"陸揚期間の定めがある航海傭船契約において始期を定めなかったときは、その期間は、前項の通知があった時から起算する。","kind":"plain"},{"t":"この場合において、不可抗力によって陸揚げをすることができない期間は、陸揚期間に算入しない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"荷受人が陸揚期間の経過後に運送品の陸揚げをした場合には、運送人は、特約がないときであっても、相当な滞船料を請求することができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ae1aac4b86cb"},{"num":"753","title":"第七百五十三条","caption":"（全部航海傭船契約の傭船者による発航前の解除）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"発航前においては、全部航海傭船契約（船舶の全部を目的とする航海傭船契約をいう。以下この節において同じ。）の傭船者は、運送賃の全額及び滞船料を支払って全部航海傭船契約の解除をすることができる。","kind":"main"},{"t":"ただし、全部航海傭船契約の解除によって運送人に生ずる損害の額が運送賃の全額及び滞船料を下回るときは、その損害を賠償すれば足りる。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"傭船者は、運送品の全部又は一部の船積みをした後に前項の規定により全部航海傭船契約の解除をしたときは、その船積み及び陸揚げに要する費用を負担しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"全部航海傭船契約の傭船者が船積期間内に運送品の船積みをしなかったときは、運送人は、その傭船者が全部航海傭船契約の解除をしたものとみなすことができる。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"157425a5de3f"},{"num":"754","title":"第七百五十四条","caption":"（全部航海傭船契約の傭船者による発航後の解除）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"発航後においては、全部航海傭船契約の傭船者は、第七百四十五条に規定する合計額及び滞船料を支払い、又は相当の担保を供しなければ、全部航海傭船契約の解除をすることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a47f090ccd33"},{"num":"755","title":"第七百五十五条","caption":"（一部航海傭船契約の解除への準用）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"第七百四十三条、第七百四十五条及び第七百五十三条第三項の規定は、船舶の一部を目的とする航海傭船契約の解除について準用する。","kind":"plain"},{"t":"この場合において、第七百四十三条第一項中「全額」とあるのは「全額及び滞船料」と、第七百四十五条中「合計額」とあるのは「合計額並びに滞船料」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2c0e5f420832"},{"num":"756","title":"第七百五十六条","caption":"（個品運送契約に関する規定の準用等）","path":["第三編　海商","第三章　海上物品運送に関する特則","第二節　航海傭船"],"paras":[{"n":"1","s":[{"t":"第七百三十八条から第七百四十二条まで（第七百三十九条第二項を除く。）、第七百四十四条、第七百四十六条及び第七百四十七条の規定は、航海傭船契約について準用する。","kind":"plain"},{"t":"この場合において、第七百四十一条第一項中「金額」とあるのは「金額及び滞船料」と、第七百四十四条中「前条」とあるのは「第七百五十三条第一項又は第七百五十五条において準用する前条」と、第七百四十七条中「この節」とあるのは「次節」と読み替えるものとする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"運送人は、前項において準用する第七百三十九条第一項の規定による運送人の損害賠償の責任を免除し、又は軽減する特約をもって船荷証券の所持人に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"79df785423f3"},{"num":"757","title":"第七百五十七条","caption":"（船荷証券の交付義務）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"運送人又は船長は、荷送人又は傭船者の請求により、運送品の船積み後遅滞なく、船積みがあった旨を記載した船荷証券（以下この節において「船積船荷証券」という。）の一通又は数通を交付しなければならない。","kind":"plain"},{"t":"運送品の船積み前においても、その受取後は、荷送人又は傭船者の請求により、受取があった旨を記載した船荷証券（以下この節において「受取船荷証券」という。）の一通又は数通を交付しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"受取船荷証券が交付された場合には、受取船荷証券の全部と引換えでなければ、船積船荷証券の交付を請求することができない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定は、運送品について現に海上運送状が交付されているときは、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"91f51eeb911e"},{"num":"758","title":"第七百五十八条","caption":"（船荷証券の記載事項）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"船荷証券には、次に掲げる事項（受取船荷証券にあっては、第七号及び第八号に掲げる事項を除く。）を記載し、運送人又は船長がこれに署名し、又は記名押印しなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"運送品の種類","kind":"plain"}]},{"n":"二","s":[{"t":"運送品の容積若しくは重量又は包若しくは個品の数及び運送品の記号","kind":"plain"}]},{"n":"三","s":[{"t":"外部から認められる運送品の状態","kind":"plain"}]},{"n":"四","s":[{"t":"荷送人又は傭船者の氏名又は名称","kind":"plain"}]},{"n":"五","s":[{"t":"荷受人の氏名又は名称","kind":"plain"}]},{"n":"六","s":[{"t":"運送人の氏名又は名称","kind":"plain"}]},{"n":"七","s":[{"t":"船舶の名称","kind":"plain"}]},{"n":"八","s":[{"t":"船積港及び船積みの年月日","kind":"plain"}]},{"n":"九","s":[{"t":"陸揚港","kind":"plain"}]},{"n":"十","s":[{"t":"運送賃","kind":"plain"}]},{"n":"十一","s":[{"t":"数通の船荷証券を作成したときは、その数","kind":"plain"}]},{"n":"十二","s":[{"t":"作成地及び作成の年月日","kind":"plain"}]}]},{"n":"２","s":[{"t":"受取船荷証券と引換えに船積船荷証券の交付の請求があったときは、その受取船荷証券に船積みがあった旨を記載し、かつ、署名し、又は記名押印して、船積船荷証券の作成に代えることができる。","kind":"plain"},{"t":"この場合においては、前項第七号及び第八号に掲げる事項をも記載しなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6740bfc3f73f"},{"num":"759","title":"第七百五十九条","caption":"（荷送人又は傭船者の通知）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"前条第一項第一号及び第二号に掲げる事項は、その事項につき荷送人又は傭船者の書面又は電磁的方法による通知があったときは、その通知に従って記載しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、同項の通知が正確でないと信ずべき正当な理由がある場合及び当該通知が正確であることを確認する適当な方法がない場合には、適用しない。","kind":"plain"},{"t":"運送品の記号について、運送品又はその容器若しくは包装に航海の終了の時まで判読に堪える表示がされていない場合も、同様とする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"荷送人又は傭船者は、運送人に対し、第一項の通知が正確でないことによって生じた損害を賠償する責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2e6689799945"},{"num":"760","title":"第七百六十条","caption":"（船荷証券の不実記載）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"運送人は、船荷証券の記載が事実と異なることをもって善意の所持人に対抗することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e9e51ea9a338"},{"num":"761","title":"第七百六十一条","caption":"（運送品に関する処分）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"船荷証券が作成されたときは、運送品に関する処分は、船荷証券によってしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a1cc67faa000"},{"num":"762","title":"第七百六十二条","caption":"（船荷証券の譲渡又は質入れ）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"船荷証券は、記名式であるときであっても、裏書によって、譲渡し、又は質権の目的とすることができる。","kind":"main"},{"t":"ただし、船荷証券に裏書を禁止する旨を記載したときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"6a55fd214b94"},{"num":"763","title":"第七百六十三条","caption":"（船荷証券の引渡しの効力）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"船荷証券により運送品を受け取ることができる者に船荷証券を引き渡したときは、その引渡しは、運送品について行使する権利の取得に関しては、運送品の引渡しと同一の効力を有する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ed89a0b4cb47"},{"num":"764","title":"第七百六十四条","caption":"（運送品の引渡請求）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"船荷証券が作成されたときは、これと引換えでなければ、運送品の引渡しを請求することができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"94419679ec12"},{"num":"765","title":"第七百六十五条","caption":"（数通の船荷証券を作成した場合における運送品の引渡し）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"陸揚港においては、運送人は、数通の船荷証券のうち一通の所持人が運送品の引渡しを請求したときであっても、その引渡しを拒むことができない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"陸揚港外においては、運送人は、船荷証券の全部の返還を受けなければ、運送品の引渡しをすることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7bd874e6ba27"},{"num":"766","title":"第七百六十六条","caption":"","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"二人以上の船荷証券の所持人がある場合において、その一人が他の所持人より先に運送人から運送品の引渡しを受けたときは、当該他の所持人の船荷証券は、その効力を失う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"1f3a2278ad5b"},{"num":"767","title":"第七百六十七条","caption":"（二人以上の船荷証券の所持人から請求を受けた場合の供託）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"二人以上の船荷証券の所持人が運送品の引渡しを請求したときは、運送人は、その運送品を供託することができる。","kind":"plain"},{"t":"運送人が第七百六十五条第一項の規定により運送品の一部を引き渡した後に他の所持人が運送品の引渡しを請求したときにおけるその運送品の残部についても、同様とする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"運送人は、前項の規定により運送品を供託したときは、遅滞なく、請求をした各所持人に対してその旨の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項に規定する場合においては、最も先に発送され、又は引き渡された船荷証券の所持人が他の所持人に優先する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"e821c674dac0"},{"num":"768","title":"第七百六十八条","caption":"（船荷証券が作成された場合の特則）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"船荷証券が作成された場合における前編第八章第二節の規定の適用については、第五百八十条中「荷送人」とあるのは、「船荷証券の所持人」とし、第五百八十一条、第五百八十二条第二項及び第五百八十七条ただし書の規定は、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d0751296b9f4"},{"num":"769","title":"第七百六十九条","caption":"（複合運送証券）","path":["第三編　海商","第三章　海上物品運送に関する特則","第三節　船荷証券等"],"paras":[{"n":"1","s":[{"t":"運送人又は船長は、陸上運送及び海上運送を一の契約で引き受けたときは、荷送人の請求により、運送品の船積み後遅滞なく、船積みがあった旨を記載した複合運送証券の一通又は数通を交付しなければならない。","kind":"plain"},{"t":"運送品の船積み前においても、その受取後は、荷送人の請求により、受取があった旨を記載した複合運送証券の一通又は数通を交付しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"第七百五十七条第二項及び第七百五十八条から前条までの規定は、複合運送証券について準用する。","kind":"plain"},{"t":"この場合において、第七百五十八条第一項中「除く。）」とあるのは、「除く。）並びに発送地及び到達地」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"060945b226ee"},{"num":"770","title":"第七百七十条","caption":"","path":["第三編　海商","第三章　海上物品運送に関する特則","第四節　海上運送状"],"paras":[{"n":"1","s":[{"t":"運送人又は船長は、荷送人又は傭船者の請求により、運送品の船積み後遅滞なく、船積みがあった旨を記載した海上運送状を交付しなければならない。","kind":"plain"},{"t":"運送品の船積み前においても、その受取後は、荷送人又は傭船者の請求により、受取があった旨を記載した海上運送状を交付しなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"海上運送状には、次に掲げる事項を記載しなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"第七百五十八条第一項各号（第十一号を除く。）に掲げる事項（運送品の受取があった旨を記載した海上運送状にあっては、同項第七号及び第八号に掲げる事項を除く。）","kind":"plain"}]},{"n":"二","s":[{"t":"数通の海上運送状を作成したときは、その数","kind":"plain"}]}]},{"n":"３","s":[{"t":"第一項の運送人又は船長は、海上運送状の交付に代えて、法務省令で定めるところにより、荷送人又は傭船者の承諾を得て、海上運送状に記載すべき事項を電磁的方法により提供することができる。","kind":"plain"},{"t":"この場合において、当該運送人又は船長は、海上運送状を交付したものとみなす。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前三項の規定は、運送品について現に船荷証券が交付されているときは、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ddb9d5877d79"},{"num":"771:787","title":"第七百七十一条から第七百八十七条まで","caption":"","path":["第三編　海商","第三章　海上物品運送に関する特則","第四節　海上運送状"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"788","title":"第七百八十八条","caption":"（船舶所有者間の責任の分担）","path":["第三編　海商","第四章　船舶の衝突"],"paras":[{"n":"1","s":[{"t":"船舶と他の船舶との衝突（次条において「船舶の衝突」という。）に係る事故が生じた場合において、衝突したいずれの船舶についてもその船舶所有者又は船員に過失があったときは、裁判所は、これらの過失の軽重を考慮して、各船舶所有者について、その衝突による損害賠償の責任及びその額を定める。","kind":"plain"},{"t":"この場合において、過失の軽重を定めることができないときは、損害賠償の責任及びその額は、各船舶所有者が等しい割合で負担する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"57b214837d00"},{"num":"789","title":"第七百八十九条","caption":"（船舶の衝突による損害賠償請求権の消滅時効）","path":["第三編　海商","第四章　船舶の衝突"],"paras":[{"n":"1","s":[{"t":"船舶の衝突を原因とする不法行為による損害賠償請求権（財産権が侵害されたことによるものに限る。）は、不法行為の時から二年間行使しないときは、時効によって消滅する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"244be2dfa1be"},{"num":"790","title":"第七百九十条","caption":"（準衝突）","path":["第三編　海商","第四章　船舶の衝突"],"paras":[{"n":"1","s":[{"t":"前二条の規定は、船舶がその航行若しくは船舶の取扱いに関する行為又は船舶に関する法令に違反する行為により他の船舶に著しく接近し、当該他の船舶又は当該他の船舶内にある人若しくは物に損害を加えた事故について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"7127fee18af8"},{"num":"791","title":"第七百九十一条","caption":"（非航海船との衝突等への準用）","path":["第三編　海商","第四章　船舶の衝突"],"paras":[{"n":"1","s":[{"t":"前三条の規定は、船舶と非航海船との事故について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5dbe2dda05e1"},{"num":"792","title":"第七百九十二条","caption":"（救助料の支払の請求等）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"船舶又は積荷その他の船舶内にある物（以下この編において「積荷等」という。）の全部又は一部が海難に遭遇した場合において、これを救助した者があるときは、その者（以下この章において「救助者」という。）は、契約に基づかないで救助したときであっても、その結果に対して救助料の支払を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船舶所有者及び船長は、積荷等の所有者に代わってその救助に係る契約を締結する権限を有する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b290b066ecdc"},{"num":"793","title":"第七百九十三条","caption":"（救助料の額）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"救助料につき特約がない場合において、その額につき争いがあるときは、裁判所は、危険の程度、救助の結果、救助のために要した労力及び費用（海洋の汚染の防止又は軽減のためのものを含む。）その他一切の事情を考慮して、これを定める。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"fea08a28670e"},{"num":"794","title":"第七百九十四条","caption":"（救助料の増減の請求）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"海難に際し契約で救助料を定めた場合において、その額が著しく不相当であるときは、当事者は、その増減を請求することができる。","kind":"plain"},{"t":"この場合においては、前条の規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"845ccc9de004"},{"num":"795","title":"第七百九十五条","caption":"（救助料の上限額）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"救助料の額は、特約がないときは、救助された物の価額（救助された積荷の運送賃の額を含む。）の合計額を超えることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"389ac3032aa4"},{"num":"796","title":"第七百九十六条","caption":"（救助料の割合等）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"数人が共同して救助した場合において、各救助者に支払うべき救助料の割合については、第七百九十三条の規定を準用する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"第七百九十二条第一項に規定する場合において、人命の救助に従事した者があるときは、その者も、前項の規定に従って救助料の支払を受けることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"b0205ebd5c16"},{"num":"797","title":"第七百九十七条","caption":"","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"救助に従事した船舶に係る救助料については、その三分の二を船舶所有者に支払い、その三分の一を船員に支払わなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定に反する特約で船員に不利なものは、無効とする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定にかかわらず、救助料の割合が著しく不相当であるときは、船舶所有者又は船員の一方は、他の一方に対し、その増減を請求することができる。","kind":"plain"},{"t":"この場合においては、第七百九十三条の規定を準用する。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"各船員に支払うべき救助料の割合は、救助に従事した船舶の船舶所有者が決定する。","kind":"plain"},{"t":"この場合においては、前条の規定を準用する。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"救助者が救助することを業とする者であるときは、前各項の規定にかかわらず、救助料の全額をその救助者に支払わなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a6720b17895a"},{"num":"798","title":"第七百九十八条","caption":"（救助料の割合の案）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"船舶所有者が前条第四項の規定により救助料の割合を決定するには、航海を終了するまでにその案を作成し、これを船員に示さなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"de553cd94070"},{"num":"799","title":"第七百九十九条","caption":"","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"船員は、前条の案に対し、異議の申立てをすることができる。","kind":"plain"},{"t":"この場合において、当該異議の申立ては、その案が示された後、当該異議の申立てをすることができる最初の港の管海官庁にしなければならない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"管海官庁は、前項の規定による異議の申立てを理由があると認めるときは、前条の案を更正することができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"船舶所有者は、第一項の規定による異議の申立てについての管海官庁の決定があるまでは、船員に対し、救助料の支払をすることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"002bf7055f88"},{"num":"800","title":"第八百条","caption":"","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"船舶所有者が第七百九十八条の案の作成を怠ったときは、管海官庁は、船員の請求により、船舶所有者に対し、その案の作成を命ずることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船舶所有者が前項の規定による命令に従わないときは、管海官庁は、自ら第七百九十七条第四項の規定による決定をすることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"52ba8c79e5c3"},{"num":"801","title":"第八百一条","caption":"（救助料を請求することができない場合）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"次に掲げる場合には、救助者は、救助料を請求することができない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"故意に海難を発生させたとき。","kind":"plain"}]},{"n":"二","s":[{"t":"正当な事由により救助を拒まれたにもかかわらず、救助したとき。","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"53b21d410c56"},{"num":"802","title":"第八百二条","caption":"（積荷等についての先取特権）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"救助料に係る債権を有する者は、救助された積荷等について先取特権を有する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の先取特権については、第八百四十三条第二項、第八百四十四条及び第八百四十六条の規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"3756017c85ac"},{"num":"803","title":"第八百三条","caption":"（救助料の支払等に係る船長の権限）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"救助された船舶の船長は、救助料の債務者に代わってその支払に関する一切の裁判上又は裁判外の行為をする権限を有する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"救助された船舶の船長は、救助料に関し、救助料の債務者のために、原告又は被告となることができる。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"前二項の規定は、救助に従事した船舶の船長について準用する。","kind":"plain"},{"t":"この場合において、これらの規定中「債務者」とあるのは、「債権者（当該船舶の船舶所有者及び海員に限る。）」と読み替えるものとする。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"前三項の規定は、契約に基づく救助については、適用しない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"ac82e6b56206"},{"num":"804","title":"第八百四条","caption":"（積荷等の所有者の責任）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"積荷等の全部又は一部が救助されたときは、当該積荷等の所有者は、当該積荷等をもって救助料に係る債務を弁済する責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"2dbf44d002ce"},{"num":"805","title":"第八百五条","caption":"（特別補償料）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"海難に遭遇した船舶から排出された油その他の物により海洋が汚染され、当該汚染が広範囲の沿岸海域において海洋環境の保全に著しい障害を及ぼし、若しくは人の健康を害し、又はこれらの障害を及ぼすおそれがある場合において、当該船舶の救助に従事した者が当該障害の防止又は軽減のための措置をとったときは、その者（以下この条において「汚染対処船舶救助従事者」という。）は、特約があるときを除き、船舶所有者に対し、特別補償料の支払を請求することができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"特別補償料の額は、前項に規定する措置として必要又は有益であった費用に相当する額とする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"汚染対処船舶救助従事者がその措置により第一項に規定する障害を防止し、又は軽減したときは、特別補償料は、当事者の請求により、前項に規定する費用に相当する額以上当該額に百分の三十（当該額が当該障害の防止又は軽減の結果に比して著しく少ないことその他の特別の事情がある場合にあっては、百分の百）を乗じて得た額を加算した額以下の範囲内において、裁判所がこれを定める。","kind":"plain"},{"t":"この場合においては、第七百九十三条の規定を準用する。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"汚染対処船舶救助従事者が同一の海難につき救助料に係る債権を有するときは、特別補償料の額は、当該救助料の額を控除した額とする。","kind":"plain"}],"items":[]},{"n":"５","s":[{"t":"汚染対処船舶救助従事者の過失によって第一項に規定する障害を防止し、又は軽減することができなかったときは、裁判所は、これを考慮して、特別補償料の額を定めることができる。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"a7f90133ee10"},{"num":"806","title":"第八百六条","caption":"（救助料に係る債権等の消滅時効）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"救助料又は特別補償料に係る債権は、救助の作業が終了した時から二年間行使しないときは、時効によって消滅する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"54ae7cc1f436"},{"num":"807","title":"第八百七条","caption":"（非航海船の救助への準用）","path":["第三編　海商","第五章　海難救助"],"paras":[{"n":"1","s":[{"t":"この章の規定は、非航海船又は非航海船内にある積荷その他の物を救助する場合について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"65213df6d35a"},{"num":"808","title":"第八百八条","caption":"（共同海損の成立）","path":["第三編　海商","第六章　共同海損"],"paras":[{"n":"1","s":[{"t":"船舶及び積荷等に対する共同の危険を避けるために船舶又は積荷等について処分がされたときは、当該処分（以下この章において「共同危険回避処分」という。）によって生じた損害及び費用は、共同海損とする。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"前項の規定は、同項の危険が過失によって生じた場合における利害関係人から当該過失のある者に対する求償権の行使を妨げない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"395c439fbe51"},{"num":"809","title":"第八百九条","caption":"（共同海損となる損害又は費用）","path":["第三編　海商","第六章　共同海損"],"paras":[{"n":"1","s":[{"t":"共同海損となる損害の額は、次の各号に掲げる区分に応じ、当該各号に定める額によって算定する。","kind":"main"},{"t":"ただし、第二号及び第四号に定める額については、積荷の滅失又は損傷のために支払うことを要しなくなった一切の費用の額を控除するものとする。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"船舶：到達の地及び時における当該船舶の価格","kind":"plain"}]},{"n":"二","s":[{"t":"積荷：陸揚げの地及び時における当該積荷の価格","kind":"plain"}]},{"n":"三","s":[{"t":"積荷以外の船舶内にある物：到達の地及び時における当該物の価格","kind":"plain"}]},{"n":"四","s":[{"t":"運送賃：陸揚げの地及び時において請求することができる運送賃の額","kind":"plain"}]}]},{"n":"２","s":[{"t":"船荷証券その他積荷の価格を評定するに足りる書類（以下この章において「価格評定書類」という。）に積荷の実価より低い価額を記載したときは、その積荷に加えた損害の額は、当該価格評定書類に記載された価額によって定める。","kind":"plain"},{"t":"積荷の価格に影響を及ぼす事項につき価格評定書類に虚偽の記載をした場合において、当該記載によることとすれば積荷の実価より低い価格が評定されることとなるときも、同様とする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"次に掲げる損害又は費用は、利害関係人が分担することを要しない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"次に掲げる物に加えた損害。","kind":"main"},{"t":"ただし、次のハに掲げる物にあっては第五百七十七条第二項第一号に掲げる場合を、次のニに掲げる物にあっては甲板積みをする商慣習がある場合を除く。","kind":"proviso"}],"items":[{"n":"イ","s":[{"t":"船舶所有者に無断で船積みがされた積荷","kind":"plain"}]},{"n":"ロ","s":[{"t":"船積みに際して故意に虚偽の申告がされた積荷","kind":"plain"}]},{"n":"ハ","s":[{"t":"高価品である積荷であって、荷送人又は傭船者が運送を委託するに当たりその種類及び価額を通知していないもの","kind":"plain"}]},{"n":"ニ","s":[{"t":"甲板上の積荷","kind":"plain"}]},{"n":"ホ","s":[{"t":"属具目録に記載がない属具","kind":"plain"}]}]},{"n":"二","s":[{"t":"特別補償料","kind":"plain"}]}]}],"proviso":true,"deleted":false,"h":"2d58fe17d54b"},{"num":"810","title":"第八百十条","caption":"（共同海損の分担額）","path":["第三編　海商","第六章　共同海損"],"paras":[{"n":"1","s":[{"t":"共同海損は、次の各号に掲げる者（船員及び旅客を除く。）が当該各号に定める額の割合に応じて分担する。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"船舶の利害関係人：到達の地及び時における当該船舶の価格","kind":"plain"}]},{"n":"二","s":[{"t":"積荷の利害関係人：次のイに掲げる額から次のロに掲げる額を控除した額","kind":"plain"}],"items":[{"n":"イ","s":[{"t":"陸揚げの地及び時における当該積荷の価格","kind":"plain"}]},{"n":"ロ","s":[{"t":"共同危険回避処分の時においてイに規定する積荷の全部が滅失したとした場合に当該積荷の利害関係人が支払うことを要しないこととなる運送賃その他の費用の額","kind":"plain"}]}]},{"n":"三","s":[{"t":"積荷以外の船舶内にある物（船舶に備え付けた武器を除く。）の利害関係人：到達の地及び時における当該物の価格","kind":"plain"}]},{"n":"四","s":[{"t":"運送人：次のイに掲げる額から次のロに掲げる額を控除した額","kind":"plain"}],"items":[{"n":"イ","s":[{"t":"第二号ロに規定する運送賃のうち、陸揚げの地及び時において現に存する債権の額","kind":"plain"}]},{"n":"ロ","s":[{"t":"船員の給料その他の航海に必要な費用（共同海損となる費用を除く。）のうち、共同危険回避処分の時に船舶及び第二号イに規定する積荷の全部が滅失したとした場合に運送人が支払うことを要しないこととなる額","kind":"plain"}]}]}]},{"n":"２","s":[{"t":"共同危険回避処分の後、到達又は陸揚げ前に船舶又は積荷等について必要費又は有益費を支出したときは、当該船舶又は積荷等については、前項第一号から第三号までに定める額は、その費用（共同海損となる費用を除く。）の額を控除した額とする。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"第一項に規定する者が共同危険回避処分によりその財産につき損害を受けたときは、その者については、同項各号に定める額は、その損害の額（当該財産について前項に規定する必要費又は有益費を支出した場合にあっては、その費用（共同海損となる費用に限る。）の額を超える部分の額に限る。）を加算した額とする。","kind":"plain"}],"items":[]},{"n":"４","s":[{"t":"価格評定書類に積荷の実価を超える価額を記載したときは、その積荷の利害関係人は、当該価格評定書類に記載された価額に応じて共同海損を分担する。","kind":"plain"},{"t":"積荷の価格に影響を及ぼす事項につき価格評定書類に虚偽の記載をした場合において、当該記載によることとすれば積荷の実価を超える価格が評定されることとなるときも、同様とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"02f6d9a1738d"},{"num":"811","title":"第八百十一条","caption":"（共同海損を分担すべき者の責任）","path":["第三編　海商","第六章　共同海損"],"paras":[{"n":"1","s":[{"t":"前条の規定により共同海損を分担すべき者は、船舶の到達（同条第一項第二号又は第四号に掲げる者にあっては、積荷の陸揚げ）の時に現存する価額の限度においてのみ、その責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"42064e79a0f3"},{"num":"812","title":"第八百十二条","caption":"（共同海損の分担に基づく債権の消滅時効）","path":["第三編　海商","第六章　共同海損"],"paras":[{"n":"1","s":[{"t":"共同海損の分担に基づく債権は、その計算が終了した時から一年間行使しないときは、時効によって消滅する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"0aa5d564a71e"},{"num":"813:814","title":"第八百十三条及び第八百十四条","caption":"","path":["第三編　海商","第六章　共同海損"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"815","title":"第八百十五条","caption":"（定義等）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"この章において「海上保険契約」とは、損害保険契約のうち、保険者（営業として保険の引受けを行うものに限る。以下この章において同じ。）が航海に関する事故によって生ずることのある損害を塡補することを約するものをいう。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"海上保険契約については、この章に別段の定めがある場合を除き、保険法（平成二十年法律第五十六号）第二章第一節から第四節まで及び第六節並びに第五章の規定を適用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"75ac14892924"},{"num":"816","title":"第八百十六条","caption":"（保険者の塡補責任）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"保険者は、この章又は海上保険契約に別段の定めがある場合を除き、保険の目的について、保険期間内に発生した航海に関する事故によって生じた一切の損害を塡補する責任を負う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"c535a5f988eb"},{"num":"817","title":"第八百十七条","caption":"","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"保険者は、海難の救助又は共同海損の分担のため被保険者が支払うべき金額を塡補する責任を負う。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"保険法第十九条の規定は、前項に規定する金額について準用する。","kind":"plain"},{"t":"この場合において、同条中「てん補損害額」とあるのは、「商法（明治三十二年法律第四十八号）第八百十七条第一項に規定する金額」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"bb02f7c474c1"},{"num":"818","title":"第八百十八条","caption":"（船舶保険の保険価額）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"船舶を保険の目的物とする海上保険契約（以下この章において「船舶保険契約」という。）については、保険期間の始期における当該船舶の価額を保険価額とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"d24ec9982342"},{"num":"819","title":"第八百十九条","caption":"（貨物保険の保険価額）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"貨物を保険の目的物とする海上保険契約（以下この章において「貨物保険契約」という。）については、その船積みがされた地及び時における当該貨物の価額、運送賃並びに保険に関する費用の合計額を保険価額とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"cf4bf75305f7"},{"num":"820","title":"第八百二十条","caption":"（告知義務）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"保険契約者又は被保険者になる者は、海上保険契約の締結に際し、海上保険契約により塡補することとされる損害の発生の可能性（以下この章において「危険」という。）に関する重要な事項について、事実の告知をしなければならない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"9c7fe2d07f01"},{"num":"821","title":"第八百二十一条","caption":"（契約締結時に交付すべき書面の記載事項）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"保険者が海上保険契約を締結した場合においては、保険法第六条第一項に規定する書面には、同項各号に掲げる事項のほか、次の各号に掲げる場合の区分に応じ、当該各号に定める事項を記載しなければならない。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"船舶保険契約を締結した場合：船舶の名称、国籍、種類、船質、総トン数、建造の年及び航行区域（一の航海について船舶保険契約を締結した場合にあっては、発航港及び到達港（寄航港の定めがあるときは、その港を含む。））並びに船舶所有者の氏名又は名称","kind":"plain"}]},{"n":"二","s":[{"t":"貨物保険契約を締結した場合：船舶の名称並びに貨物の発送地、船積港、陸揚港及び到達地","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"70e7205188db"},{"num":"822","title":"第八百二十二条","caption":"（航海の変更）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"保険期間の始期の到来前に航海の変更をしたときは、海上保険契約は、その効力を失う。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"保険期間内に航海の変更をしたときは、保険者は、その変更以後に発生した事故によって生じた損害を塡補する責任を負わない。","kind":"main"},{"t":"ただし、その変更が保険契約者又は被保険者の責めに帰することができない事由によるものであるときは、この限りでない。","kind":"proviso"}],"items":[]},{"n":"３","s":[{"t":"到達港を変更し、その実行に着手した場合においては、海上保険契約で定める航路を離れないときであっても、航海の変更をしたものとみなす。","kind":"plain"}],"items":[]}],"proviso":true,"deleted":false,"h":"c81c09f5f4ed"},{"num":"823","title":"第八百二十三条","caption":"（著しい危険の増加）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"次に掲げる場合には、保険者は、その事実が生じた時以後に発生した事故によって生じた損害を塡補する責任を負わない。","kind":"main"},{"t":"ただし、当該事実が当該事故の発生に影響を及ぼさなかったとき、又は保険契約者若しくは被保険者の責めに帰することができない事由によるものであるときは、この限りでない。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"被保険者が発航又は航海の継続を怠ったとき。","kind":"plain"}]},{"n":"二","s":[{"t":"被保険者が航路を変更したとき。","kind":"plain"}]},{"n":"三","s":[{"t":"前二号に掲げるもののほか、保険契約者又は被保険者が危険を著しく増加させたとき。","kind":"plain"}]}]}],"proviso":true,"deleted":false,"h":"8a56d142b9eb"},{"num":"824","title":"第八百二十四条","caption":"（船舶の変更）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"貨物保険契約で定める船舶を変更したときは、保険者は、その変更以後に発生した事故によって生じた損害を塡補する責任を負わない。","kind":"main"},{"t":"ただし、その変更が保険契約者又は被保険者の責めに帰することができない事由によるものであるときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"e1b62ee6ebd0"},{"num":"825","title":"第八百二十五条","caption":"（予定保険）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"貨物保険契約において、保険期間、保険金額、保険の目的物、約定保険価額、保険料若しくはその支払の方法、船舶の名称又は貨物の発送地、船積港、陸揚港若しくは到達地（以下この条において「保険期間等」という。）につきその決定の方法を定めたときは、保険法第六条第一項に規定する書面には、保険期間等を記載することを要しない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"保険契約者又は被保険者は、前項に規定する場合において、保険期間等が確定したことを知ったときは、遅滞なく、保険者に対し、その旨の通知を発しなければならない。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"保険契約者又は被保険者が故意又は重大な過失により遅滞なく前項の通知をしなかったときは、貨物保険契約は、その効力を失う。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"96ce67f206ab"},{"num":"826","title":"第八百二十六条","caption":"（保険者の免責）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"保険者は、次に掲げる損害を塡補する責任を負わない。","kind":"main"},{"t":"ただし、第四号に掲げる損害にあっては、保険契約者又は被保険者が発航の当時同号に規定する事項について注意を怠らなかったことを証明したときは、この限りでない。","kind":"proviso"}],"items":[{"n":"一","s":[{"t":"保険の目的物の性質若しくは瑕疵又はその通常の損耗によって生じた損害","kind":"plain"}]},{"n":"二","s":[{"t":"保険契約者又は被保険者の故意又は重大な過失（責任保険契約にあっては、故意）によって生じた損害","kind":"plain"}]},{"n":"三","s":[{"t":"戦争その他の変乱によって生じた損害","kind":"plain"}]},{"n":"四","s":[{"t":"船舶保険契約にあっては、発航の当時第七百三十九条第一項各号（第七百七条及び第七百五十六条第一項において準用する場合を含む。）に掲げる事項を欠いたことにより生じた損害","kind":"plain"}]},{"n":"五","s":[{"t":"貨物保険契約にあっては、貨物の荷造りの不完全によって生じた損害","kind":"plain"}]}]}],"proviso":true,"deleted":false,"h":"b28db287034a"},{"num":"827","title":"第八百二十七条","caption":"（貨物の損傷等の場合の塡補責任）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"保険の目的物である貨物が損傷し、又はその一部が滅失して到達地に到着したときは、保険者は、第一号に掲げる額の第二号に掲げる額に対する割合を保険価額（約定保険価額があるときは、当該約定保険価額）に乗じて得た額を塡補する責任を負う。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"当該貨物に損傷又は一部滅失がなかったとした場合の当該貨物の価額から損傷又は一部滅失後の当該貨物の価額を控除した額","kind":"plain"}]},{"n":"二","s":[{"t":"当該貨物に損傷又は一部滅失がなかったとした場合の当該貨物の価額","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"61a3f8796ec6"},{"num":"828","title":"第八百二十八条","caption":"（不可抗力による貨物の売却の場合の塡補責任）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"航海の途中において不可抗力により保険の目的物である貨物が売却されたときは、保険者は、第一号に掲げる額から第二号に掲げる額を控除した額を塡補する責任を負う。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"保険価額（約定保険価額があるときは、当該約定保険価額）","kind":"plain"}]},{"n":"二","s":[{"t":"当該貨物の売却によって得た代価から運送賃その他の費用を控除した額","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"84fe034e9414"},{"num":"829","title":"第八百二十九条","caption":"（告知義務違反による解除）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"保険者は、保険契約者又は被保険者が、危険に関する重要な事項について、故意又は重大な過失により事実の告知をせず、又は不実の告知をしたときは、海上保険契約を解除することができる。","kind":"plain"},{"t":"この場合においては、保険法第二十八条第二項（第一号に係る部分に限る。）及び第四項並びに第三十一条第二項（第一号に係る部分に限る。）の規定を準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"14260be42445"},{"num":"830","title":"第八百三十条","caption":"（相互保険への準用）","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"この章の規定は、相互保険について準用する。","kind":"main"},{"t":"ただし、その性質がこれを許さないときは、この限りでない。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"64064d12af43"},{"num":"831:841","title":"第八百三十一条から第八百四十一条まで","caption":"","path":["第三編　海商","第七章　海上保険"],"paras":[{"n":"1","s":[{"t":"削除","kind":"plain"}],"items":[]}],"proviso":false,"deleted":true,"h":"c687dbf4f33e"},{"num":"842","title":"第八百四十二条","caption":"（船舶先取特権）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"次に掲げる債権を有する者は、船舶及びその属具について先取特権を有する。","kind":"plain"}],"items":[{"n":"一","s":[{"t":"船舶の運航に直接関連して生じた人の生命又は身体の侵害による損害賠償請求権","kind":"plain"}]},{"n":"二","s":[{"t":"救助料に係る債権又は船舶の負担に属する共同海損の分担に基づく債権","kind":"plain"}]},{"n":"三","s":[{"t":"国税徴収法（昭和三十四年法律第百四十七号）若しくは国税徴収の例によって徴収することのできる請求権であって船舶の入港、港湾の利用その他船舶の航海に関して生じたもの又は水先料若しくは引き船料に係る債権","kind":"plain"}]},{"n":"四","s":[{"t":"航海を継続するために必要な費用に係る債権","kind":"plain"}]},{"n":"五","s":[{"t":"雇用契約によって生じた船長その他の船員の債権","kind":"plain"}]}]}],"proviso":false,"deleted":false,"h":"833146e611f1"},{"num":"843","title":"第八百四十三条","caption":"（船舶先取特権の順位）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"前条各号に掲げる債権に係る先取特権（以下この章において「船舶先取特権」という。）が互いに競合する場合には、その優先権の順位は、同条各号に掲げる順序に従う。","kind":"main"},{"t":"ただし、同条第二号に掲げる債権（救助料に係るものに限る。）に係る船舶先取特権は、その発生の時において既に生じている他の船舶先取特権に優先する。","kind":"proviso"}],"items":[]},{"n":"２","s":[{"t":"同一順位の船舶先取特権を有する者が数人あるときは、これらの者は、その債権額の割合に応じて弁済を受ける。","kind":"main"},{"t":"ただし、前条第二号から第四号までに掲げる債権にあっては、同一順位の船舶先取特権が同時に生じたものでないときは、後に生じた船舶先取特権が前に生じた船舶先取特権に優先する。","kind":"proviso"}],"items":[]}],"proviso":true,"deleted":false,"h":"cc8667013cdb"},{"num":"844","title":"第八百四十四条","caption":"（船舶先取特権と他の先取特権との競合）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"船舶先取特権と他の先取特権とが競合する場合には、船舶先取特権は、他の先取特権に優先する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"98ff4d830c31"},{"num":"845","title":"第八百四十五条","caption":"（船舶先取特権と船舶の譲受人）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"船舶所有者がその船舶を譲渡したときは、譲受人は、その登記をした後、船舶先取特権を有する者に対し、一定の期間内にその債権の申出をすべき旨を公告しなければならない。","kind":"plain"},{"t":"この場合において、その期間は、一箇月を下ることができない。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船舶先取特権を有する者が前項の期間内に同項の申出をしなかったときは、その船舶先取特権は、消滅する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"19f3dbd8902d"},{"num":"846","title":"第八百四十六条","caption":"（船舶先取特権の消滅）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"船舶先取特権は、その発生後一年を経過したときは、消滅する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"02ba1a62e877"},{"num":"847","title":"第八百四十七条","caption":"（船舶抵当権）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"登記した船舶は、抵当権の目的とすることができる。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船舶の抵当権は、その属具に及ぶ。","kind":"plain"}],"items":[]},{"n":"３","s":[{"t":"船舶の抵当権には、不動産の抵当権に関する規定を準用する。","kind":"plain"},{"t":"この場合において、民法第三百八十四条第一号中「抵当権を実行して競売の申立てをしないとき」とあるのは、「抵当権の実行としての競売の申立て若しくはその提供を承諾しない旨の第三取得者に対する通知をせず、又はその通知をした債権者が抵当権の実行としての競売の申立てをすることができるに至った後一週間以内にこれをしないとき」と読み替えるものとする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"6fa43bdaf342"},{"num":"848","title":"第八百四十八条","caption":"（船舶抵当権と船舶先取特権等との競合）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"船舶の抵当権と船舶先取特権とが競合する場合には、船舶先取特権は、船舶の抵当権に優先する。","kind":"plain"}],"items":[]},{"n":"２","s":[{"t":"船舶の抵当権と先取特権（船舶先取特権を除く。）とが競合する場合には、船舶の抵当権は、民法第三百三十条第一項に規定する第一順位の先取特権と同順位とする。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"197869253a89"},{"num":"849","title":"第八百四十九条","caption":"（質権設定の禁止）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"登記した船舶は、質権の目的とすることができない。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"421d31658a64"},{"num":"850","title":"第八百五十条","caption":"（製造中の船舶への準用）","path":["第三編　海商","第八章　船舶先取特権及び船舶抵当権"],"paras":[{"n":"1","s":[{"t":"この章の規定は、製造中の船舶について準用する。","kind":"plain"}],"items":[]}],"proviso":false,"deleted":false,"h":"5f8277f0035f"}]};
